// Від Матфея — Біблія, переклад Патріарха Філарета. Згенеровано scripts/build_bible.py, не правте вручну.
import type { BChap } from '../types';
const C: BChap[] = [{"v":["Книга родоводу Ісуса Христа, Сина Давидового, Сина Авраамового.","Авраам породив Ісаака; Ісаак породив Якова; Яків породив Іуду та братів його;","Іуда породив Фареса і Зару від Фамари; Фарес породив Есрома; Есром породив Арама;","Арам породив Аминадава; Аминадав породив Наасона; Наасон породив Салмона;","Салмон породив Вооза від Рахави; Вооз породив Овида від Руфи; Овид породив Єссея;","Єссей породив Давида царя; Давид цар породив Соломона від дружини Урієвої;","Соломон породив Ровоама; Ровоам породив Авию; Авия породив Асу;","Аса породив Іосафата; Іосафат породив Іорама; Іорам породив Озію;","Озія породив Іоафама; Іоафам породив Ахаза; Ахаз породив Єзекію;","Єзекія породив Манассію; Манассія породив Амона; Амон породив Іосію;","Іосія породив Іоакима; Іоаким породив Єхонію та братів його до переселення вавилонського.","По переселенні ж вавилонському Єхонія породив Салафиїла; Салафиїл породив Зоровавеля;","Зоровавель породив Авиуда; Авиуд породив Єлиакима; Єлиаким породив Азора;","Азор породив Садока; Садок породив Ахима; Ахим породив Еліуда;","Еліуд породив Єлеазара; Єлеазар породив Матфана; Матфан породив Якова;","Яків породив Йосифа, чоловіка Марії, від Якої народився Ісус, названий Христом.","Отже, всіх поколінь від Авраама до Давида чотирнадцять родів; і від Давида до переселення вавилонського чотирнадцять родів; і від переселення вавилонського до Христа чотирнадцять родів.","Різдво Ісуса Христа було так: по зарученні Матері Його Марії з Йосифом, перш ніж зійтися їм, виявилося, що Вона має в утробі від Духа Святого.","Йосиф же, чоловік Її, будучи праведним і не бажаючи ославити Її, хотів потай відпустити Її.","Та щойно він помислив це, як ось ангел Господній з’явився йому уві сні, промовляючи: Йосифе, сину Давидів! Не бійся прийняти Марію, жону твою, бо зачате в Ній є від Духа Святого.","Народить же Вона Сина, і наречеш Йому ім’я Ісус, бо Він спасе людей Своїх від гріхів їхніх.","Це ж усе сталося, щоб збулося сказане Господом через пророка, який говорить:","ось Діва в утробі прийме й народить Сина, і наречуть ім’я Йому Еммануїл, що означає: з нами Бог.","Прокинувшись, Йосиф зробив, як звелів йому ангел Господній, і прийняв жону свою.","І не знав Її, поки й породила Сина Свого первістка, і він нарік ім’я Йому: Ісус."],"x":{"1":"52.3.23","2":"0.21.2|0.25.26|0.29.35","3":"0.38.30|0.46.12|7.4.18|12.2.5","5":"7.4.21|12.2.11","6":"8.17.12|9.12.24","7":"10.11.43|12.3.10","10":"11.20.21|12.3.13","11":"11.23.34|12.3.16|13.36.4","12":"12.3.17|14.3.2","18":"52.1.27","21":"52.1.31|54.4.12|58.2.2|62.3.24","23":"31.7.14","25":"52.2.21"}},{"v":["Коли ж Ісус народився у Вифлеємі Юдейському у дні царя Ірода, волхви* зі сходу прийшли до Єрусалима, кажучи:","де є народжений Цар Юдейський? Бо ми бачили зірку Його на сході і прийшли поклонитися Йому.","Почувши це, Ірод цар стривожився, й увесь Єрусалим з ним.","І, зібравши всіх первосвящеників і книжників народних, питав у них: де мав би народитися Христос?","Вони ж сказали йому: у Вифлеємі юдейському, бо так написано пророком:","і ти, Вифлеєме, земле Іудина, нічим не менший від інших володінь Іудиних; бо з тебе вийде Вождь, Який упасе народ Мій, Ізраїля.","Тоді Ірод, потайки покликавши волхвів, вивідав від них час з’явлення зірки","і пославши їх до Вифлеєма, сказав: підіть, старанно розвідайте про Немовля і, коли знайдете, сповістіть мене, щоб і мені піти поклонитися Йому.","Вони, вислухавши царя, пішли. І ось зірка, яку бачили вони на сході, йшла перед ними, аж поки, нарешті, прийшла і зупинилась над місцем, де було Немовля.","Побачивши зірку, вони зраділи радістю вельми великою.","І, увійшовши в дім, побачили Немовля з Марією, Матір’ю Його, і, впавши, поклонилися Йому; і, відкривши скарби свої, принесли Йому дари: золото, ладан і смирну*.","І, одержавши уві сні одкровення не повертатися до Ірода, іншою дорогою відійшли до країни своєї.","Коли ж вони відійшли, то ангел Господній уві сні з’явився Йосифові, говорячи: устань, візьми Немовля і Матір Його та біжи в Єгипет і будь там, доки не скажу тобі, бо хоче Ірод шукати Немовля, щоб погубити Його.","Він же, вставши, узяв Немовля і Матір Його вночі та й пішов у Єгипет","і був там до смерти Іродової, щоб збулося сказане Господом через пророка, який говорить: з Єгипту покликав Я Сина Мого.","Тоді Ірод, побачивши себе осміяним волхвами, дуже розгнівався і послав повбивати усіх немовлят у Вифлеємі і в усіх околицях його, — від двох років і менше — за часом, про який вивідав у волхвів.","Тоді збулося сказане через пророка Єремію, який говорить:","голос в Рамі чути, плач і ридання та голосіння велике; Рахиль плаче за дітьми своїми і не хоче втішитися, бо нема їх.","Як помер Ірод, то ангел Господній уві сні з’явився Йосифові в Єгипті","і говорить: устань, візьми Немовля і Матір Його та йди в землю Ізраїлеву, бо вже померли ті, що шукали душу Немовляти.","Він же, вставши, узяв Немовля і Матір Його і прийшов у землю Ізраїлеву.","Почувши ж, що Архелай царює в Юдеї замість Ірода, батька свого, побоявся йти туди; а, одержавши уві сні одкровення, пішов у землю Галилейську.","І, прийшовши, оселився в місті, яке зветься Назарет, щоб збулося сказане через пророків, що Він Назореєм наречеться."],"x":{"1":"52.2.6","2":"3.24.17|31.60.3","6":"43.5.2|53.7.42","11":"31.60.6","15":"38.11.1","18":"32.31.15","23":"6.13.5|31.11.1-2"},"n":{"1":["Мудреці."],"11":["Запашна рідина."]}},{"v":["У ті дні приходить Іоан Хреститель і проповідує в пустелі Юдейській,","і каже: покайтеся, наблизилось бо Царство Небесне.","Бо Він є Той, про Якого сказав пророк Ісая: глас вопіющого в пустелі: приготуйте путь Господеві, прямими зробіть стезі Йому.","Сам же Іоан мав одяг з верблюжого волоса і пояс шкіряний на стегнах своїх, а їжею його були акриди* та мед дикий.","Тоді виходили до нього Єрусалим, і вся Юдея, і вся околиця Йорданська;","І хрестилися в Йордані від нього, сповідаючи гріхи свої.","А побачивши багато фарисеїв і саддукеїв, що йшли до нього хреститися, Іоан сказав їм: поріддя єхиднове! Хто навчив вас тікати від грядущого гніву?","Створіть же плід, достойний покаяння.","І не починайте говорити в собі: отця маємо Авраама. Кажу бо вам, що Бог може з каміння цього звести дітей Авраамові. Вже й сокира біля кореня дерева лежить:","бо всяке дерево, що не приносить доброго плоду, рубають і кидають в огонь.","Я хрещу вас водою на покаяння, але Той, Хто гряде після мене, Сильніший за мене; я недостойний понести взуття Його; Він хреститиме вас Духом Святим і вогнем;","Його лопата* в руці у Нього, і Він очистить тік Свій і збере пшеницю Свою в житницю, а полову спалить вогнем невгасимим.","Тоді приходить Ісус з Галилеї на Йордан до Іоана хреститися від нього.","Іоан же стримував Його і говорив: мені треба хреститися від Тебе, і чи Тобі приходити до мене?","Але Ісус сказав йому у відповідь: облиш нині, бо так належить нам виконати всяку правду. Тоді Іоан допускає Його.","І, охрестившись, Ісус вийшов зразу ж з води, — і ось розкрилися Йому небеса, і побачив Іоан Духа Божого, Який сходив, мов голуб, і спускався на Нього.","І ось голос лунає з неба, який говорить: Це є Син Мій Улюблений, в Ньому Моє благовоління."],"x":{"1":"51.1.4|52.3.3|53.1.28|54.13.24","3":"31.40.3|51.1.3|52.3.4|53.1.23","4":"51.1.6","7":"50.23.33|52.3.7","9":"53.8.39|54.13.26","10":"50.7.19","11":"51.1.8|52.3.16|53.1.26|54.1.5|54.2.2-4","12":"52.3.17","13":"51.1.9|52.3.21","16":"51.1.10|52.3.21|53.1.32","17":"51.1.11|52.3.22|53.5.37|57.1.17|68.1.13"},"n":{"4":["Вид сарани."],"12":["Якою віють хліб."]}},{"v":["Тоді Ісус виведений був Духом у пустелю, щоб спокушав Його диявол.","І постився сорок днів і сорок ночей, наостанку зголоднів.","І, приступивши до Нього, спокусник сказав: якщо Ти Син Божий, скажи, щоб каміння це хлібами стало.","Він же сказав йому у відповідь: написано: не хлібом єдиним житиме людина, але всяким словом, що виходить з уст Божих.","Тоді узяв Його диявол до святого міста і поставив Його на крилі храму,","та й каже Йому: якщо Ти є Син Божий, кинься вниз, бо написано: ангелам Своїм заповість про Тебе, щоб оберігали Тебе, і на руки візьмуть Тебе, щоб не спіткнувся об камінь ногою Твоєю.","Сказав же йому Ісус: написано також: не спокушай Господа Бога твого.","Знову бере Його диявол на дуже високу гору і показує Йому всі царства світу і славу їхню,","та й говорить Йому: це все Тобі дам, якщо, впавши, поклонишся мені.","Тоді Ісус говорить йому: відійди від Мене, сатано, бо написано: Господу Богу твоєму поклоняйся і Йому Єдиному служи.","Тоді залишив Його диявол, і ось ангели приступили й служили Йому.","Коли ж почув Ісус, що Іоан відданий під варту, пішов до Галилеї.","І, залишивши Назарет, прийшов і оселився в Капернаумі приморському, в краях Завулонових і Неффалимових,","щоб збулося сказане пророком Ісаєю, який говорить:","земле Завулонова і земле Неффалимова, за Йорданом на шляху приморському, Галилеє язичників.","Народ, що сидів у темряві, побачив світло велике, і тим, що перебувають у країні й тіні смерти, світло засяяло їм.","Відтоді почав Ісус проповідувати й говорити: покайтеся, наблизилося бо Царство Небесне.","Проходячи ж біля моря Галилейського, Він побачив двох братів: Симона, що звався Петром, і Андрія, брата його, які закидали сіті в море, бо вони були рибалками.","Та й каже їм: ідіть за Мною, і зроблю вас ловцями людей.","І вони зараз же, покинувши сіті, пішли за Ним.","І, відійшовши звідтіля, побачив інших двох братів: Якова Зеведеєвого та Іоана, брата його, у човні із Зеведеєм, батьком їхнім, які лагодили сіті свої, і покликав їх.","Вони, одразу ж покинувши човен і батька свого, пішли за Ним.","І ходив Ісус по всій Галилеї, навчаючи в синагогах їхніх і проповідуючи Євангеліє Царства, зціляючи всяку недугу і всяку неміч у людях.","І розійшлася чутка про Нього по всій Сирії; і приводили до Нього всіх немічних, хворих на всілякі недуги, й одержимих, і біснуватих, і сновид, і розслаблених — і Він зціляв їх.","І йшло за Ним багато народу з Галилеї, і з Десятиграддя, і з Єрусалима, і з Юдеї, і з іншого боку Йордана."],"x":{"4":"4.8.3|52.4.4","6":"25.90.11-12|52.4.10","7":"4.6.16|52.4.12","10":"4.6.13|4.10.20|52.4.8","12":"51.1.14|52.4.14|53.4.43","16":"31.9.1-2","17":"51.1.15","18":"51.1.16","24":"51.6.55","25":"52.6.17"}},{"v":["Побачивши народ, Він зійшов на гору; і, коли сів, приступили до Нього ученики Його.","І, відкривши уста Свої, навчав їх, промовляючи:","Блаженні убогі духом, бо їхнє є Царство Небесне.","Блаженні ті, що плачуть, бо вони втішаться.","Блаженні лагідні, бо вони успадкують землю.","Блаженні голодні і спраглі правди, бо вони наситяться.","Блаженні милостиві, бо вони помилувані будуть.","Блаженні чисті серцем, бо вони Бога побачать.","Блаженні миротворці, бо вони синами Божими назвуться.","Блаженні гнані за правду, бо їхнє є Царство Небесне.","Блаженні ви, коли ганьбитимуть вас і гнатимуть, і зводитимуть на вас усяке лихослів’я та наклепи — Мене ради.","Радуйтесь і веселіться, бо велика нагорода ваша на небесах. Так гнали і пророків, які були до вас.","Ви — сіль землі. Якщо ж сіль втратить силу, то чим зробиш її солоною? Вона вже ні до чого не придатна, хіба що бути викинутою геть на потоптання людям.","Ви — світло світу. Не може сховатися місто, яке стоїть на верху гори.","І не запалюють світильник, щоб поставити його під посудину, але на свічник, — і світить всім у домі.","Так нехай сяє світло ваше перед людьми, щоб вони бачили ваші добрі діла і прославляли Отця вашого Небесного.","Не думайте, що Я прийшов порушити Закон або Пророків: не порушити прийшов Я, а виконати.","Бо істинно кажу вам: доки існуватимуть небо і земля, жодна йота чи жодна риска не перейде із закону, поки не здійсниться все.","Отже, якщо хто порушить одну з цих заповідей найменших і навчить того людей, той найменшим назветься в Царстві Небесному; а хто виконає і навчить, той великим назветься в Царстві Небесному.","Кажу бо вам, якщо праведність ваша не перевершить праведности книжників і фарисеїв, то ви не ввійдете до Царства Небесного.","Ви чули, що було сказано древнім: не вбивай, а хто уб’є, підлягає суду.","Я ж кажу вам, що всякий, хто гнівається на брата свого даремно, підлягає суду; а хто скаже на брата свого: «рака»*, підлягає синедріону*; а хто скаже: «потвора», підлягає геєні вогненній.","Отже, коли ти принесеш дар твій до жертовника і там згадаєш, що брат твій має щось проти тебе,","залиш там дар твій перед жертовником і піди перше помирися з братом твоїм, і тоді прийди й принеси дар твій.","Мирися з суперником твоїм швидко, доки ти в дорозі з ним, щоб суперник не віддав тебе судді, а суддя не віддав би тебе слузі, і не вкинули б тебе у в’язницю.","Істинно кажу тобі: ти не вийдеш звідти, поки не віддаси останній кодрант*.","Ви чули, що було сказано древнім: не чини перелюбу.","А Я кажу вам, що всякий, хто погляне на жінку, жадаючи її, вже вчинив перелюб з нею в серці своєму.","Якщо ж праве око твоє спокушає тебе, вирви його і кинь від себе, бо краще для тебе, щоб загинув один з членів твоїх, аніж щоб усе тіло твоє було ввергнуте в геєну вогненну.","І коли правиця твоя спокушає тебе, відсічи її та кинь від себе: бо краще для тебе, щоб загинув один з членів твоїх, аніж щоб усе тіло твоє було ввергнуте в геєну.","Сказано також: коли хто розводиться з жінкою своєю, нехай дасть їй лист про розлучення.","А Я кажу вам: хто розведеться з жінкою своєю, хіба що через її любодійство, призводить її до перелюбства, і хто візьме шлюб з розлученою, той перелюбствує.","Ще чули ви, що було сказано древнім: не клянися неправдиво, а виконуй перед Господом клятви твої.","А Я кажу вам — не клястися зовсім: ні небом, бо воно є престолом Божим;","ні землею, бо вона є підніжжям ніг Його; ні Єрусалимом, бо це місто великого Царя.","І головою твоєю не клянися, бо не можеш жодної волосини білою або чорною зробити.","Нехай буде слово ваше: так — так; ні — ні, а що зверх цього, те від лукавого.","Ви чули, що було сказано: око за око і зуб за зуб.","А Я кажу вам не противитися злу. Але якщо тебе хто вдарить у праву твою щоку, підстав йому і другу.","І тому, хто захоче судитися з тобою і верхній одяг твій взяти, віддай йому і сорочку.","І хто примусить тебе іти з ним одне поприще, іди з ним два.","Тому, хто просить у тебе, дай; і від того, хто хоче в тебе позичити, не відвертайся.","Ви чули, що було сказано: люби ближнього твого і ненавидь ворога твого.","А Я кажу вам: любіть ворогів ваших, благословляйте тих, хто проклинає вас, добро творіть тим, хто ненавидить вас, і моліться за тих, хто кривдить і гонить вас,","щоб ви були синами Отця вашого Небесного, бо Він сонцем Своїм осяває злих і добрих і посилає дощ на праведних і на неправедних.","Бо коли ви любите тих, хто любить вас, яка вам нагорода? Чи не те саме і митарі роблять?","І коли ви вітаєте тільки друзів ваших, що особливого робите? Чи не так само і язичники чинять?","Отже, будьте досконалі, як Отець ваш Небесний досконалий."],"x":{"3":"52.6.20","4":"31.61.2-3|52.6.21","5":"25.36.11","8":"25.23.4","9":"75.12.14","10":"56.3.14","11":"52.6.22|56.4.14","12":"50.21.35","13":"51.9.50|52.14.34","14":"67.2.15","15":"51.4.21|52.8.16|52.11.33","16":"56.2.12|67.2.15","18":"52.16.17","21":"1.20.13|4.5.17|50.19.18|51.10.19|52.18.20","25":"52.12.58","27":"1.20.14|4.5.18","29":"4.13.6-8|50.18.8-9|51.9.43:47","31":"4.24.1|50.19.7|51.10.4:11|52.16.18|63.7.10","33":"2.19.12|4.23.21|1.20.7","37":"55.5.12","38":"1.21.24|2.24.20|4.19.21","39":"52.6.29|55.3.13|62.12.17|63.6.7|69.5.15","42":"4.15.7|52.6.34","43":"2.19.18|50.22.39|51.12.31|55.2.8|62.13.9","44":"52.6.27|52.23.34|54.7.60|63.4.12","45":"52.6.35"},"n":{"22":["Нікчемний чоловік.","Верховне судилище."],"26":["Дрібна монета."]}},{"v":["Стережіться, не творіть милостині вашої перед людьми для того, щоб вони бачили вас: інакше не буде вам нагороди від Отця вашого Небесного.","Отже, коли твориш милостиню, не сурми перед собою, як роблять лицеміри в синагогах і на вулицях, щоб прославляли їх люди. Істинно кажу вам: вони вже мають нагороду свою.","У тебе ж, як твориш милостиню, нехай ліва рука твоя не знає, що робить правиця твоя,","щоб милостиня твоя була потаємною; і Отець твій, Який бачить таємне, воздасть тобі явно.","І, коли молишся, не будь як лицеміри, які люблять молитися у синагогах і на перехрестях, зупиняючись, щоб бачили їх люди. Істинно кажу вам: вони вже мають нагороду свою.","Ти ж, коли молишся, увійди до кімнати твоєї і, зачинивши двері твої, помолись Отцю твоєму, Який у таїні, і Отець твій, Який бачить таємне, воздасть тобі явно.","А молячись, не говоріть зайвого, як язичники, бо вони думають, що в багатослів’ї своєму почуті будуть.","Не уподібнюйтесь їм, бо знає Отець ваш, чого ви потребуєте, раніше за ваше прохання до Нього.","Моліться ж так: Отче наш, що єси на небесах, нехай святиться ім’я Твоє;","нехай прийде Царство Твоє; нехай буде воля Твоя, як на небі, так і на землі.","Хліб наш насущний дай нам сьогодні;","І прости нам провини наші, як і ми прощаємо винуватцям нашим;","І не введи нас у спокусу, але визволи нас від лукавого. Бо Твоє є Царство, і сила, і слава навіки. Амінь.","Бо якщо ви прощатимете людям провини їхні, то простить і вам Отець ваш Небесний.","А коли не будете прощати людям провин їхніх, то і Отець ваш не простить вам провин ваших.","Коли ж постите, не будьте сумні, як лицеміри, бо вони потьмарюють обличчя свої, щоб показати людям, що постять вони. Істинно кажу вам: вони вже мають нагороду свою.","Ти ж, коли постиш, намасти голову твою і вмий обличчя твоє,","щоб не показувати людям, що ти постиш, але Отцю твоєму, — Який у таїні; і Отець твій, Який бачить таємне, воздасть тобі явно.","Не збирайте собі скарбів на землі, де черв і тля точать і де злодії підкопують і крадуть.","Збирайте ж собі скарби на небі, де ні черв, ні тля не точать і де злодії не підкопують і не крадуть,","бо де скарб ваш, там буде й серце ваше.","Світильником тіла є око. Отже, якщо око твоє буде чистим, то і все тіло твоє буде світлим;","коли ж око твоє буде нечистим, то і все тіло твоє темним буде. Отже, якщо світло, що в тобі, є темрявою, то яка ж тоді темрява?","Ніхто не може двом господарям служити: бо або одного полюбить, а другого буде ненавидіти; або одного триматиметься, а другим знехтує. Не можете служити Богові й мамоні*.","Задля цього кажу вам: не піклуйтеся для душі вашої, що вам їсти чи пити, ні для тіла вашого, у що вдягнутися. Чи душа не більша за їжу, а тіло — за одяг?","Погляньте на птахів небесних: вони не сіють, не жнуть, не збирають у житниці; і Отець ваш Небесний годує їх. Хіба ж ви не набагато кращі за них?","Та й хто з вас, турбуючись, може додати собі зросту хоч на один лікоть?","І про одяг чого піклуєтесь? Подивіться на лілеї польові, як вони ростуть: не трудяться і не прядуть;","кажу ж вам: що й Соломон у всій славі своїй не одягався так, як кожна з них;","якщо ж траву польову, що сьогодні є, а завтра буде вкинута в піч, Бог так зодягає, то хіба не набагато краще зодягне вас, маловіри!","Тож не турбуйтеся і не кажіть: що нам їсти? чи що пити? або: у що одягтися?","Бо всього цього язичники шукають; знає бо Отець ваш Небесний, що ви маєте потребу в усьому цьому.","Шукайте ж спершу Царства Божого і правди Його, і все це додасться вам.","Отже, не піклуйтеся про завтрашній день, бо завтра саме за себе піклуватиметься. Досить кожному дневі своїх турбот."],"x":{"2":"62.12.8","9":"52.11.2","14":"30.28.2|51.11.25","20":"52.12.21:33|71.6.19","22":"52.11.34","24":"52.16.13","25":"25.54.23|52.12.22|56.5.7","33":"51.10.30|52.12.31|71.4.8"},"n":{"24":["Багатство."]}},{"v":["Не судіть, щоб і вас не судили;","бо яким судом судите, таким судитимуть і вас, і якою мірою міряєте, такою відміряється й вам.","І чому ж ти бачиш скалку в оці брата твого, а колоди, що є в оці твоєму, не відчуваєш?","Або, як скажеш братові твоєму: дай я витягну скалку з ока твого, коли колода в оці твоїм?","Лицеміре, вийми спершу колоду з ока твого, і тоді побачиш, як вийняти скалку з ока брата твого.","Не давайте святого псам і не кидайте перлів ваших перед свиньми, щоб вони не потоптали їх ногами своїми і, обернувшись, не пороздирали й вас.","Просіть, і дасться вам; шукайте, і знайдете; стукайте, і відчинять вам;","бо кожен, хто просить, одержує, і хто шукає, знаходить, і тому, хто стукає, відчиняють.","Чи є між вами така людина, яка, коли син її попросить у неї хліба, подала б йому камінь?","І коли попросить риби, подала б йому змію?","Отже, якщо ви, будучи злими, вмієте дари добрі давати дітям вашим, тим паче Отець ваш Небесний дасть блага тим, хто просить у Нього.","Отже, все, чого бажаєте, щоб вам робили люди, так і ви робіть їм, — бо в цьому є Закон і Пророки.","Входьте вузькими воротами, бо просторі ворота і широка дорога ведуть до погибелі, і багато хто йде ними.","А вузькі ворота і тісна дорога ведуть у життя, і мало тих є, хто знаходить їх.","Остерігайтеся лжепророків, які приходять до вас в одежі овечій, а всередині — вовки хижі.","По плодах їхніх пізнаєте їх. Хіба збирають виноград з терня або смокви з будяків?","Так усяке добре дерево і плоди добрі родить, а погане дерево і плоди погані родить.","Не може дерево добре плоди погані родити, ні дерево погане плоди добрі родити.","Всяке дерево, що не дає плоду доброго, зрубують і у вогонь кидають.","Тож за їхніми плодами пізнаєте їх.","Не кожен, хто говорить Мені: Господи! Господи! — увійде в Царство Небесне, а той, хто виконує волю Отця Мого Небесного.","Багато хто скаже Мені того дня: Господи! Господи! Чи не Твоїм ім’ям ми пророкували, і чи не Твоїм ім’ям бісів виганяли, і чи не Твоїм ім’ям багато чудес творили?","І тоді скажу їм: Я ніколи не знав вас, відійдіть від Мене, хто чинить беззаконня.","Отже, всякого, хто слухає ці слова Мої і виконує їх, уподібню мужеві мудрому, який збудував будинок свій на камені;","І пішов дощ, і розлилися річки, і знялися вітри, і ринули на будинок той, і він не впав, бо був збудований на камені.","А всякий, хто слухає ці слова Мої і не виконує їх, уподібниться мужеві нерозумному, який збудував будинок свій на піску;","І пішов дощ, і розлилися річки, і знялися вітри, і налягли на будинок той; і він упав, і руйнування його було велике.","І коли Ісус скінчив слова ці, народ дивувався вченню Його,","бо Він учив їх, як Той, Хто має владу, а не як книжники і фарисеї."],"x":{"1":"52.6.37|62.2.1|63.4.5","2":"51.4.24|52.6.38","3":"52.6.41","7":"50.21.22|51.11.24|52.11.9|53.14.13|55.1.6","9":"52.11.11","12":"18.4.15|52.6.31","13":"52.13.24","15":"32.23.16|50.24.4|58.4.1","18":"52.6.43","19":"50.3.10|53.15.6","21":"52.6.46|53.6.40|55.1.22|62.2.13","23":"25.6.9|52.13.25:27","24":"52.6.47-48","28":"50.22.33|51.1.22|52.4.32"}},{"v":["Коли ж Він зійшов з гори, слідом за Ним пішло багато народу.","І ось підійшов прокажений і, кланяючись Йому, сказав: Господи, коли хочеш, можеш мене очистити.","Ісус, простягши руку, доторкнувся до нього і сказав: хочу, очисться. І він у ту ж мить очистився від прокази.","І говорить йому Ісус: гляди ж, нікому не розповідай, але піди покажися священикові і принеси дар, який повелів у законі Мойсей, на свідчення їм.","А як увійшов Ісус до Капернаума, підійшов до Нього сотник і благав Його:","Господи, слуга мій вдома лежить розслаблений і тяжко страждає.","І говорить йому Ісус: Я прийду і зцілю його.","Сотник же у відповідь сказав: Господи! Я недостойний, щоб Ти увійшов під покрівлю мою; але промов тільки слово, і видужає слуга мій.","Бо і я — людина підвладна, але, маючи під собою воїнів, кажу одному: іди, і йде; і другому: прийди, і приходить; і слузі моєму: зроби це, і зробить.","Почувши це, Ісус здивувався і сказав тим, що йшли за Ним: істинно кажу вам, і в Ізраїлі не знайшов Я такої віри.","Кажу ж вам, що багато прийдуть зі сходу й заходу і возляжуть з Авраамом, Ісааком і Яковом у Царстві Небесному;","А сини Царства вигнані будуть у пітьму непроглядну: там буде плач і скрегіт зубів.","І сказав Ісус сотникові: іди, і, як вірував ти, нехай буде тобі. І одужав слуга його в ту ж мить.","Прийшовши до Петрової господи, Ісус побачив тещу його, що лежала в гарячці,","і доторкнувся до руки її, і гарячка покинула її; і вона встала і слугувала Йому.","Коли ж настав вечір, привели до Нього багатьох біснуватих, і Він вигнав духів словом і зцілив усіх недужих,","щоб справдилося сказане пророком Ісаєю, який говорить: Він узяв на Себе недуги наші і поніс хвороби.","А як побачив Ісус довкола Себе багато народу, звелів ученикам відпливти на другий бік.","Тоді один книжник, підійшовши, сказав Йому: Учителю, я піду за Тобою, куди б Ти не пішов.","І каже йому Ісус: лисиці мають нори і птахи небесні — гнізда, Син же Людський не має де голови прихилити.","Інший же з учеників Його сказав Йому: Господи! Дозволь мені перше піти і поховати батька мого.","Але Ісус сказав йому: іди за Мною і залиш мертвим ховати своїх мерців.","І як увійшов Він у човен, за Ним пішли ученики Його.","І ось піднялися хвилі великі на морі, аж човен покривало; Він же спав.","Тоді ученики Його, підійшовши до Нього, розбудили Його і сказали: Господи, рятуй нас, гинемо.","І говорить їм: чого ви такі боязкі, маловіри? Відтак, уставши, заборонив вітрам і морю, і настала велика тиша.","Люди ж, дивуючись, говорили: Хто Цей, що і вітри, й море слухають Його?","І коли Він прибув на другий бік, до країни Гергесинської, Його зустріли двоє біснуватих, що вийшли з гробниць, дуже люті, так що ніхто не міг пройти тією дорогою.","І ось вони закричали: що Тобі до нас, Ісусе, Сину Божий? Прийшов Ти сюди передчасно мучити нас.","А віддалік паслося велике стадо свиней.","І біси благали Його: якщо виженеш нас, то пошли нас у стадо свиней.","І Він сказав їм: ідіть. І вони, вийшовши, пішли у стадо свиней. І ось усе стадо кинулося з кручі в море і втопилось у воді.","Пастухи ж побігли і, прийшовши у місто, розповіли про все і про те, що було з біснуватими.","І ось усе місто вийшло назустріч Ісусові; і, побачивши Його, просили, щоб Він відійшов від їхнього краю."],"x":{"2":"51.1.40|52.5.12","4":"2.14.3-4|51.1.44|52.5.14","5":"52.7.2","12":"50.22.13","14":"51.1.29-30|52.4.38","16":"51.1.32|52.4.40","17":"31.53.4|56.2.24","19":"52.9.57","22":"52.9.60","23":"51.4.35-36|52.8.22","28":"51.5.1-2|52.8.27","29":"51.1.24"}},{"v":["Тоді Він, увійшовши в човен, переплив назад і прибув до Свого міста.","І ось принесли до Нього розслабленого, що лежав на постелі. І, побачивши віру їхню, Ісус сказав розслабленому: дерзай, чадо! Прощаються тобі гріхи твої!","При цьому деякі з книжників говорили собі: Він богохульствує.","Ісус же, бачачи помисли їхні, промовив: навіщо ви думаєте лукаве в серцях своїх?","Бо що легше — сказати: прощаються тобі гріхи, чи сказати: встань і ходи?","Та щоб знали ви, що Син Людський має владу на землі прощати гріхи. Тоді говорить розслабленому: встань, візьми постіль твою та йди у дім твій.","І той устав, узяв постіль свою і пішов у дім свій.","Народ же, побачивши це, здивувався і прославив Бога, Який дав таку владу людям.","Проходячи звідти, Ісус побачив чоловіка, що сидів на митниці, на ймення Матфей, і каже йому: іди за Мною. І той устав і пішов за Ним.","І коли Ісус возлежав у домі, прийшло багато митарів і грішників і возлежали з Ним і з учениками Його.","Побачивши те, фарисеї сказали ученикам Його: чому Учитель ваш їсть і п’є з митарями і грішниками?","Ісус же, почувши це, сказав їм: не здорові потребують лікаря, а недужі,","підіть та навчіться, що означає: милости хочу, а не жертви. Бо Я прийшов прикликати не праведників, але грішників до покаяння.","Тоді приступають до Нього ученики Іоанові і кажуть: чому ми і фарисеї постимо багато, Твої ж ученики не постять?","І сказав їм Ісус: чи можуть весільні друзі сумувати, поки з ними жених? Але настануть дні, коли відберуть у них жениха, і тоді поститимуть.","Ніхто ж бо на старий одяг не накладає латки з нової тканини, бо відірветься від старого, і дірка буде ще гірша.","Не вливають також вина молодого в старі міхи, а інакше прорвуться міхи, і вино витече, і міхи пропадуть; але вливають вино молоде в нові міхи, і зберігається те і друге.","Коли Він говорив їм це, підійшов до Нього якийсь начальник і, кланяючись Йому, сказав: дочка моя нині померла, але Ти прийди, поклади на неї руку Свою, і буде жива.","І, вставши, Ісус за ним пішов, і ученики Його.","І ось жінка, що дванадцять років страждала на кровотечу, підійшовши ззаду, доторкнулася до краю одягу Його,","бо вона казала сама собі: як тільки доторкнусь до одягу Його, одужаю.","Ісус же, обернувшись і побачивши її, сказав: дерзай, дочко! Віра твоя спасла тебе. І одужала жінка з того ж часу.","Прийшов Ісус до господи начальника і побачив сопілкарів та людей, що голосили.","І сказав їм: відійдіть, бо не вмерла дівчина, а спить. І глузували з Нього.","Коли ж людей було випроваджено, Він, увійшовши, взяв її за руку, і дівчина встала.","І рознеслася чутка про це по всій землі тій.","Коли йшов Ісус звідтіля, за Ним слідом ішли двоє сліпих і кричали: помилуй нас, Ісусе, Сину Давидів!","Коли ж Він увійшов у дім, сліпі приступили до Нього. І говорить їм Ісус: чи віруєте, що Я можу це зробити? Вони говорять Йому: так, Господи!","Тоді він доторкнувся до очей їхніх і сказав: за вірою вашою нехай буде вам.","І відкрилися очі їхні; і сказав їм Ісус суворо: пильнуйте ж, щоб ніхто не довідався.","Вони ж, вийшовши, прославляли Його по всій землі тій.","Коли ж ті виходили, то привели до Нього чоловіка німого, біснуватого.","І коли біса було вигнано, німий почав говорити. І народ, дивуючись, казав: ніколи не було такого в Ізраїлі.","Фарисеї ж говорили: силою князя бісівського виганяє Він бісів.","І ходив Ісус по всіх містах і селах, навчаючи в їхніх синагогах, проповідуючи Євангеліє Царства і зціляючи всякі недуги і всяку неміч у людях.","Бачачи безліч людей, Він змилосердився над ними, бо вони були зморені й розпорошені, як вівці, що не мають пастиря.","Тоді говорить до учеників Своїх: жнива багато, а женців замало.","Тож благайте Господаря жнива, щоб вислав женців на жниво Своє."],"x":{"1":"51.2.1","2":"51.2.3|52.5.18","5":"51.2.9|52.5.23","9":"51.2.14|52.5.27","13":"38.6.6|50.12.7|51.2.17|52.5.32","14":"51.2.18|52.5.33","16":"51.2.21|52.5.36","18":"51.5.22|52.8.41","20":"51.5.25","27":"50.20.30","32":"52.11.14","34":"50.12.24|51.3.22|52.11.15","35":"51.6.6|52.13.22","36":"31.53.6|51.6.34","37":"52.10.2|53.4.35","38":"70.3.1"}},{"v":["Прикликавши дванадцять учеників Своїх, Він дав їм владу над нечистими духами, щоб виганяли їх і зціляли всяку недугу і всяку неміч.","Дванадцяти ж апостолів імена такі: перший Симон, що зветься Петром, і Андрій, брат його, Яків Зеведеїв та Іоан, брат його,","Филип і Варфоломій, Фома і Матфей-митар, Яків Алфеїв і Леввей, прозваний Фадеєм,","Симон Кананіт та Іуда Іскаріотський, який і зрадив Його.","Цих дванадцятьох послав Ісус і заповів їм, промовляючи: на путь до язичників не ходіть і в місто самарянське не входьте;","а йдіть краще до овець загиблих дому Ізраїлевого;","ходячи ж, проповідуйте, кажучи, що наблизилося Царство Небесне;","хворих зціляйте, прокажених очищайте, мертвих воскрешайте, бісів виганяйте: задарма одержали, задарма давайте.","Не беріть з собою ні золота, ні срібла, ані міді у пояси свої,","ні торбини на дорогу, ні двох одежин, ні взуття, ані посоха, бо той, хто трудиться, достойний нагороди своєї.","В яке б місто або селище не ввійшли ви, довідуйтесь, хто в ньому достойний є, і там залишайтесь, доки не вийдете;","а входячи в дім, привітайте його, кажучи: мир дому цьому.","І якщо буде дім достойний, то мир ваш зійде на нього; якщо ж не буде достойний, то мир ваш до вас повернеться.","А коли хто не прийме вас і не послухає слів ваших, то, виходячи з дому чи з міста того, обтрусіть порох з ніг ваших.","Істинно кажу вам: відрадніше буде землі Содомській і Гоморрській у день судний, аніж місту тому.","Ось Я посилаю вас, як овець поміж вовків: отже, будьте мудрі, як змії, і лагідні, як голуби.","Остерігайтеся ж людей: бо вони видаватимуть вас на судилища і в своїх синагогах битимуть вас,","і поведуть вас до правителів і царів заради Мене на свідчення їм та язичникам.","Коли ж видаватимуть вас, не турбуйтеся, як або що говорити; бо в той час дано буде вам, що сказати,","бо не ви будете говорити, а Дух Отця вашого говоритиме у вас.","Видасть же брат брата на смерть і батько сина; і повстануть діти на батьків і уб’ють їх;","і будуть вас ненавидіти всі за ім’я Моє; а хто витерпить до кінця, той спасенний буде.","Коли ж гнатимуть вас в одному місті, біжіть у інше. Бо істинно кажу вам: не встигнете обійти ще міст Ізраїлевих, як прийде Син Людський.","Учень не вищий за вчителя і слуга не вищий за господаря свого.","Досить для учня, щоб він був як учитель його, і для слуги, щоб він був як господар його. Якщо господаря дому назвали Вельзевулом, то чи не тим більше — домашніх його?","Отже, не бійтесь їх, бо нема нічого прихованого, що не відкрилося б, і потайного, що не стало б відомим.","Що кажу вам у темряві, говоріть при світлі, і що чуєте на вухо, проповідуйте на покрівлях.","І не бійтеся тих, що вбивають тіло, а душі не можуть убити; але бійтесь більше Того, Хто може і душу, і тіло погубити в геєні.","Чи не дві малі пташки продаються за один асарій*? І жодна з них не впаде на землю без волі Отця вашого;","у вас же і волосся на голові все полічено;","не бійтеся ж: ви дорожчі за багатьох малих пташок.","Отже, кожного, хто визнає Мене перед людьми, того визнаю і Я перед Отцем Моїм Небесним.","А хто зречеться Мене перед людьми, зречуся того і Я перед Отцем Моїм Небесним.","Не думайте, що Я прийшов принести мир на землю; не мир прийшов Я принести, а меч.","Бо Я прийшов розлучити сина з батьком його, і дочку з матір’ю її, і невістку із свекрухою її.","І вороги людини — домашні її.","Хто любить батька чи матір більше, ніж Мене, недостойний Мене; і хто любить сина чи дочку більше, ніж Мене, недостойний Мене;","і хто не бере хрест свій і не йде слідом за Мною, той недостойний Мене.","Хто зберігає душу свою, загубить її, а хто загубить душу свою заради Мене, збереже її.","Хто вас приймає, той Мене приймає, а хто приймає Мене, приймає Того, Хто послав Мене;","хто приймає пророка в ім’я пророка, одержить винагороду пророка; і хто приймає праведника в ім’я праведника, одержить винагороду праведника.","І хто напоїть одного з малих цих чашею холодної води, тільки в ім’я ученика, істинно кажу вам, не втратить нагороди своєї."],"x":{"1":"51.3.14|52.9.1","6":"50.15.24","7":"52.9.2","9":"51.6.8|52.9.3","10":"52.10.7|71.5.18","12":"52.10.5","14":"51.6.11|52.9.5|54.13.51","16":"52.10.3|62.16.19|64.1.12","19":"51.13.11|52.12.11","24":"52.6.40|53.13.16|53.15.20","25":"50.9.34","26":"51.4.22|52.8.17|52.12.2","28":"52.12.4","29":"52.12.6","32":"51.8.38|52.9.26|52.12.8","33":"72.2.12","34":"52.12.51","36":"43.7.6","37":"52.14.26","38":"50.16.24|51.8.34","39":"51.8.35|52.9.24|53.12.25","40":"52.10.16|53.13.20","42":"51.9.41"},"n":{"29":["Дрібна монета."]}},{"v":["І сталося, коли Ісус закінчив наставляти дванадцятьох учеників Своїх, то пішов звідти, щоб учити й проповідувати в містах їхніх.","Іоан же, почувши у в’язниці про діла Христові, послав двох з учнів своїх","запитати Його: чи Ти Той, Хто має прийти, чи нам іншого чекати?","І сказав їм Ісус у відповідь: підіть та розкажіть Іоанові, що чуєте і бачите:","сліпі прозрівають і криві ходять, прокажені очищаються і глухі чують, мертві воскресають і убогі благовістять;","і блаженний той, хто не спокуситься через Мене.","Коли ж вони відійшли, Ісус почав говорити людям про Іоана: на що дивитися ходили ви в пустелю? Чи на тростину, що вітер колише?","На що ж дивитися ходили ви? Чи на людину, вдягнену в м’який одяг? Ті, що носять м’який одяг, у палацах царських живуть.","На що ж дивитися ходили ви? На пророка? Так, кажу вам, більш як пророка.","Цей бо є той, про якого написано: ось Я посилаю ангела Мого перед лицем Твоїм, який приготує дорогу Твою перед Тобою.","Істинно кажу вам: не було серед народжених жінками більшого за Іоана Хрестителя; але найменший у Царстві Небесному більший за нього.","Від днів же Іоана Хрестителя донині Царство Небесне силою здобувається, і хто докладає зусилля, здобуває його,","бо всі пророки і закон провіщали до Іоана.","І коли хочете знати, він є Ілля, що має прийти.","Хто має вуха, щоб слухати, нехай слухає!","Кому ж уподібню рід цей? Він подібний до дітей, що сидять на вулиці і, звертаючись до своїх товаришів,","кажуть: ми грали вам на сопілках, та ви не танцювали; ми співали вам жалібних пісень, та ви не ридали.","Бо прийшов Іоан, який не їсть, не п’є; і кажуть: біса має.","Прийшов Син Людський, Який їсть і п’є, і кажуть: цей чоловік, який любить їсти й пити вино, митарям друг і грішникам. І виправдалась премудрість від синів своїх.","Тоді почав Ісус докоряти містам, у яких явлено було найбільше чудес Його, за те, що вони не покаялися.","Горе тобі, Хоразине! Горе тобі, Вифсаїдо! Бо якби у Тирі та Сидоні сталися чудеса, що явлені були у вас, то вони давно покаялися б у веретищі й попелі.","Але кажу вам: Тиру й Сидону відрадніше буде в день судний, ніж вам.","І ти, Капернауме, що до небес піднісся, до пекла зійдеш, бо якби в Содомі сталися чудеса, що явлені були в тобі, то зостався б він до сьогоднішнього дня.","Але кажу вам, що землі Содомській відрадніше буде в день судний, ніж тобі.","Продовжуючи далі, Ісус сказав: славлю Тебе, Отче, Господи неба й землі, що Ти втаїв це від премудрих та розумних і відкрив те немовлятам.","Так, Отче, бо таке було Твоє благовоління.","Усе Мені передано Отцем Моїм, і ніхто не знає Сина, тільки Отець; і Отця ніхто не знає, тільки Син, і той, кому Син схоче відкрити.","Прийдіть до Мене, всі струджені і обтяжені, і Я заспокою вас;","візьміть ярмо Моє на себе і навчіться від Мене, бо Я лагідний і смиренний серцем, і знайдете спокій душам вашим;","бо ярмо Моє — благо, і тягар Мій легкий."],"x":{"2":"52.7.18-19","3":"4.18.15","5":"31.29.18|31.35.5","10":"49.3.1|51.1.2|52.7.27","12":"52.16.16","14":"49.4.5","16":"52.7.31","19":"52.7.34-35","21":"52.10.13","25":"25.8.3|52.10.21|63.1.27|64.11.3","27":"50.16.17|53.3.35|53.6.46","29":"32.6.16","30":"58.5.3"}},{"v":["У той час проходив Ісус у суботу засіяними ланами; ученики ж Його зголодніли і почали зривати колоски та їсти.","Фарисеї ж, побачивши це, сказали Йому: ось ученики Твої роблять те, чого не годиться робити в суботу.","Він же сказав їм: хіба ви не читали, що зробив Давид, коли зголоднів сам і ті, що були з ним?","Як він увійшов у храм Божий і їв хліби принесення, яких не можна було їсти ні йому, ні тим, що з ним були, а тільки одним священикам?","Або хіба ви не читали в законі, що по суботах священики в храмі порушують суботу, однак невинні?","Говорю ж вам, що тут Той, Хто більший від храму.","Коли б ви знали, що значить: милости хочу, а не жертви, то не осуджували б невинних.","Бо Син Людський є господарем і суботи.","І відійшовши звідти, прийшов Він до їхньої синагоги.","І ось був там чоловік, що мав суху руку, і спитали Його, чи дозволено зціляти в суботу, щоб звинуватити Його.","Він же сказав їм: чи є між вами людина, яка, маючи одну вівцю, якщо вона впаде в суботу в яму, не візьме і не витягне її?","Наскільки ж людина краща за вівцю! Отже, дозволено в суботу добро творити.","Тоді каже чоловікові тому: простягни руку твою. Той простягнув, і стала вона здоровою, як і друга.","Фарисеї ж, вийшовши, радилися проти Нього, як би Його погубити. Але Ісус, дізнавшись, пішов звідти.","І пішло за Ним багато народу, і Він зцілив їх усіх.","І заборонив, щоб не являли Його.","Щоб справдилося сказане Ісайєю пророком, який говорить:","це Отрок Мій, Якого Я обрав. Улюблений Мій, до Якого благоволить душа Моя. Покладу Дух Мій на Нього, і Він провістить народам суд.","Не буде ні суперечити, ні кричати, і ніхто не почує на перехрестях голосу Його;","тростини надломленої не переломить, і льону тліючого не загасить, доки не доведе суду до перемоги;","і на ім’я Його уповатимуть народи.","Тоді привели до Нього біснуватого — сліпого і німого; і Він зцілив його, так що сліпий і німий став говорити й бачити.","І дивувався весь народ і говорив: чи не Цей є Христос, Син Давидів?","Фарисеї ж, почувши це, сказали: Він виганяє бісів не інакше, як силою Вельзевула, князя бісівського.","Але Ісус, знаючи думки їхні, сказав їм: усяке царство, що розділилося в собі, запустіє; і всяке місто чи дім, що розділилися у собі, не встоять.","І якщо сатана сатану виганяє, то він розділився в собі, як же встоїть царство його?","І якщо Я силою Вельзевула виганяю бісів, то чиєю силою виганяють сини ваші? Тому вони будуть вам суддями.","Коли ж Я Духом Божим виганяю бісів, то настало для вас Царство Боже.","Або як може хто увійти в дім сильного та пограбувати його майно, якщо перше не зв’яже сильного? І тоді розграбує дім його.","Хто не зі Мною, той проти Мене; і хто не збирає зі Мною, той марнує.","Тому кажу вам: всякий гріх і хула простяться людям, але на Духа хула не проститься людям.","І коли хто скаже слово на Сина Людського, проститься йому, якщо ж хто скаже на Духа Святого, не проститься йому ні в цьому житті, ні в майбутньому.","Або визнайте дерево добрим і плід його добрим; або визнайте дерево поганим і плід його поганим, бо дерево пізнається з плоду.","Поріддя єхиднове, як можете добре говорити, злими будучи? Від повноти бо серця говорять уста.","Добра людина з доброго скарбу* виносить добре, а зла людина зі злого скарбу виносить лихе.","Кажу ж вам, що за всяке пусте слово, яке скажуть люди, вони дадуть відповідь у день судний:","бо за словами своїми будеш виправданий і за словами своїми будеш осуджений.","Тоді деякі з книжників і фарисеїв сказали: Учителю, хочемо від Тебе знамення бачити.","Він же сказав їм у відповідь: рід лукавий і перелюбний знамення шукає, та знамення не дасться йому, крім знамення Іони пророка.","Бо як був Іона в утробі кита три дні і три ночі, так буде і Син Людський в серці землі три дні і три ночі.","Мужі ниневійські постануть на суд з родом цим і осудять його, бо вони покаялись після проповіді Іониної; а ось тут Більший за Іону.","Цариця південна постане на суд з родом цим і осудить його, бо вона прийшла від краю землі послухати премудрість Соломонову; а ось тут Більший за Соломона.","Коли ж нечистий дух вийде з людини, то блукає безводними місцями, шукаючи спокою, і не знаходить.","Тоді каже: повернуся в дім мій, звідки я вийшов. І, прийшовши, знаходить його порожнім, заметеним і прибраним.","Тоді йде і бере з собою сім інших духів, лютіших за себе, і вони, ввійшовши, живуть там; і буде для тієї людини останнє гірше від першого. Так буде і роду цьому лукавому.","Коли ж Він ще промовляв до народу, Мати і брати Його стояли надворі, бажаючи говорити з Ним.","І хтось сказав Йому: он Мати Твоя і брати Твої стоять надворі і бажають говорити з Тобою.","Він же відповів тому, хто говорив до Нього: хто Мати Моя і хто брати Мої?","І, показавши рукою Своєю на учеників Своїх, сказав: ось мати Моя і брати Мої;","бо хто творитиме волю Отця Мого Небесного, той брат Мій, і сестра, і мати Моя."],"x":{"1":"4.23.25|51.2.23|52.6.1","4":"1.29.32|8.21.6|51.2.26|52.6.4","5":"2.8.31|2.24.9","7":"38.6.6|50.9.13","9":"51.3.1|52.6.6","21":"31.42.1-4","22":"52.11.14","24":"50.9.34|51.3.22|52.11.15","25":"51.3.24|52.11.17","31":"51.3.28|52.12.10|58.5.16","34":"52.6.45","37":"52.19.22","38":"50.16.1|63.1.22","39":"52.11.29","40":"42.2.1","41":"42.3.5|52.11.32","42":"10.10.1|13.9.1|52.11.31","43":"52.11.24","45":"57.2.20|75.6.4","46":"51.3.31|52.8.19","50":"53.15.14"},"n":{"35":["У грецькому тексті — скарбу серця."]}},{"v":["Того ж дня, вийшовши з дому, Ісус сів біля моря.","І зібралось до Нього багато народу, так що Йому довелося ввійти у човен і сісти; а весь народ стояв на березі.","І говорив їм притчами багато, кажучи: ось вийшов сівач сіяти;","І коли він сіяв, одне зерно впало при дорозі, і прилетіли птахи і поклювали його.","Інше впало на місця кам’янисті, де небагато було землі, і скоро зійшло, бо земля була неглибока.","Коли ж зійшло сонце, зів’яло і, оскільки не мало кореня, засохло.","Інше впало в терня, і виросло терня, і заглушило його;","інше впало на добру землю і дало плід: одно в стократ, а друге в шістдесят, інше в тридцять разів.","Хто має вуха слухати, нехай слухає!","І, приступивши, ученики сказали Йому: чому притчами говориш їм?","Він сказав їм у відповідь: тому, що вам дано розуміти тайни Царства Небесного, а їм не дано.","Бо хто має, тому дасться і примножиться, а хто не має, у того відніметься і те, що має.","Тому говорю їм притчами, що вони, дивлячись, не бачать, і, слухаючи, не чують, і не розуміють;","і збувається над ними пророцтво Ісаї, яке говорить: слухом почуєте — і не зрозумієте, і очима дивитись будете — і не побачите.","Бо згрубіло серце людей цих, і вухами туго чують, і очі свої стулили, щоб не побачити очима, і не почути вухами, і серцем не зрозуміти, і не навернутися, щоб Я зцілив їх.","Ваші ж очі блаженні, бо бачать, і вуха ваші, бо чують.","Бо істинно кажу вам, що багато хто з пророків і праведників бажали бачити те, що ви бачите, і не бачили, і чути те, що ви чуєте, і не чули.","Ви ж вислухайте значення притчі про сівача.","До кожного, хто слухає слово про Царство і не розуміє, приходить лукавий і краде посіяне в серці його — це те, що посіяне при дорозі.","А посіяне на кам’янистих місцях означає того, хто слухає слово і зразу ж з радістю сприймає його,","але не має кореня в собі, будучи нестійким; коли ж настає скрута або гоніння через слово це, відразу спокушається.","А посіяне між терням — це той, хто слухає слово, але турботи віку цього і спокуса багатством заглушують слово, і воно буває безплідним.","Посіяне ж в добру землю — це той, хто слухає слово, і розуміє, і приносить плід, і творить — один у стократ, другий в шістдесят, а інший в тридцять разів.","Іншу притчу запропонував їм, кажучи: Царство Небесне подібне до чоловіка, що посіяв добре насіння на полі своїм;","коли ж люди спали, прийшов ворог його і насіяв кукіль між пшеницею, і пішов.","Коли зійшов посів і показався плід, тоді з’явився і кукіль.","Прийшли раби господаря і сказали йому: господарю, чи не добре насіння ти сіяв на полі твоїм? Звідки ж взявся кукіль?","Він же сказав їм: людина-ворог це зробила. А раби сказали йому: чи не хочеш ти, щоб ми пішли і випололи його?","Але він сказав: ні, бо, вибираючи кукіль, щоб ви не вирвали разом з ним і пшеницю.","Залиште рости разом те і те до жнив; а в жнива я скажу женцям: зберіть спершу кукіль і зв’яжіть його у снопи, щоб спалити; а пшеницю зберіть у житницю мою.","Іншу притчу запропонував Він їм, кажучи: Царство Небесне подібне до гірчичного зерна, яке взяв чоловік і посіяв на полі своїм.","Воно, хоч і найменше з усіх зерен, але, коли виросте, буває більше за будь-яке зілля і стає деревом, так що птахи небесні прилітають і ховаються у гілках його.","Іншу притчу сказав Він їм: Царство Небесне подібне до закваски, яку жінка взяла і поклала на три мірки борошна, доки все не вкисне.","Усе це говорив Ісус людям притчами, і без притчі нічого не говорив їм,","щоб збулося сказане через пророка, який говорить: відкрию в притчах уста Мої, сповіщу сокровенне від створення світу.","Тоді Ісус, залишивши людей, увійшов у дім. І, приступивши до Нього, ученики Його сказали: роз’ясни нам притчу про кукіль на полі.","Він же сказав їм у відповідь: Той, Хто посіяв добре насіння, є Син Людський;","поле — це світ; добре насіння — це сини Царства, а кукіль — сини лукавого;","ворог, що його посіяв, є диявол; жнива — це кінець світу, а женці — ангели.","Отже, як збирають кукіль і спалюють вогнем, так буде при кінці світу цього:","пошле Син Людський ангелів Своїх, і зберуть з Царства Його всі спокуси і тих, що чинять беззаконня,","і вкинуть їх у піч вогняну; там буде плач і скрегіт зубів.","Тоді праведники засяють, як сонце, в Царстві Отця їхнього. Хто має вуха слухати, нехай слухає!","Ще Царство Небесне подібне до скарбу, захованого на полі, який знайшов чоловік і приховав, і на радощах іде й продає все, що має, і купує поле те.","Ще Царство Небесне подібне до купця, який шукає добрі перли,","і, знайшовши одну коштовну перлину, іде й продає усе, що має, і купує її.","Ще Царство Небесне подібне до невода, закинутого в море, що назбирав усякої всячини;","коли ж наповнився, його витягли на берег і, сівши, вибрали добре в посуд, а погане викинули геть.","Так буде при кінці світу: зійдуть ангели, і відлучать злих від праведних,","і вкинуть їх у піч вогняну: там буде плач і скрегіт зубів.","І каже їм Ісус: чи зрозуміли ви все це? Вони говорять Йому: так, Господи!","Він же сказав їм: ось тому кожен книжник, навчений про Царство Небесне, подібний до господаря, який виносить із свого скарбу нове й старе.","І, коли скінчив Ісус притчі ці, пішов звідти.","І, прийшовши до Своєї батьківщини, вчив їх у синагозі їхній, так що всі дивувалися й говорили: звідки в Ньому премудрість ця і сили?","Чи Він не син теслі? Чи не Його Мати зветься Марією і брати Його Яків та Іосія, і Симон, та Іуда?","І сестри Його чи не всі між нами? Звідки ж у Нього це все?","І спокушалися Ним. Ісус же сказав їм: не буває пророка без честі, хіба що тільки на батьківщині своїй і в домі своїм.","І не створив там багатьох чудес через невір’я їхнє."],"x":{"3":"51.4.2|52.8.4","12":"50.25.29|51.4.25|52.8.18|52.19.26","14":"51.4.12|52.8.10|53.12.40|54.28.26|62.11.8","15":"31.6.9-10","16":"52.10.23","17":"56.1.10","18":"51.4.15|52.8.11","31":"51.4.30|52.13.18","33":"52.13.20","34":"51.4.33","35":"25.77.2|25.48.4","39":"39.3.13|76.14.15","43":"29.3.7|37.12.3","54":"51.6.1|52.4.16","55":"53.6.42","57":"51.6.4|52.4.24|53.4.44"}},{"v":["У той час почув Ірод четвертовладник чутку про Ісуса","і сказав прислужникам своїм: це Іоан Хреститель; він воскрес із мертвих, і тому чудеса діються ним.","Бо Ірод узяв Іоана, зв’язав його і посадив у в’язницю через Іродіаду, жінку Филипа, брата свого,","тому що Іоан говорив йому: не личить тобі мати її.","І хотів убити його, та побоявся народу, бо вважали його пророком.","Коли був день народження Ірода, дочка Іродіади танцювала посеред зібрання і догодила Іродові,","тому він поклявся дати їй, чого б вона не попросила.","Вона ж, з намови матері своєї, сказала: дай мені тут на блюді голову Іоана Хрестителя.","І засмутився цар; але, заради клятви і тих, що возлежали з ним, звелів дати їй.","І послав відсікти голову Іоана у в’язниці.","І принесли голову його на блюді і дали дівчині, а та віднесла матері своїй.","Ученики ж його, прийшовши, взяли тіло і поховали його; пішли і сповістили Ісуса.","І, почувши про те, Ісус відплив звідти на човні у безлюдне місце один; а народ, довідавшись, пішов за Ним з міст пішки.","І, вийшовши, Ісус побачив багато людей, змилосердився над ними і зцілив недужих їхніх.","Як настав вечір, приступили до Нього ученики Його і кажуть: місце тут пустинне і час уже пізній; відпусти людей, нехай підуть у селища і куплять собі що їсти.","Ісус же сказав їм: не треба їм іти, дайте ви їм їсти.","Вони ж кажуть Йому: у нас тут тільки п’ять хлібів і дві рибини.","Він сказав: принесіть їх Мені сюди.","І звелів народові возлягти на траву і, взявши п’ять хлібів і дві рибини, підняв очі на небо, благословив і, переломивши, дав ученикам хліби, а ученики — народові.","І їли всі і наситились; і набрали залишків дванадцять повних кошиків;","а тих, що їли, було близько п’яти тисяч чоловіків, крім жінок та дітей.","І зараз же звелів Ісус ученикам Своїм сісти в човен і пливти раніше за Нього на той бік, поки Він відпустить людей.","І, відпустивши народ, Він зійшов на гору помолитися на самоті; і ввечері залишився там один.","А човен був уже на середині моря, і било його хвилями, бо вітер був супротивний.","У четверту ж сторожу ночі пішов Ісус до них, ідучи по морю.","І ученики, побачивши, що Він іде по морю, стривожились і говорили: це привид. І зі страху закричали.","Але Ісус зараз же заговорив до них і сказав: заспокойтесь! Це Я, не бійтеся.","Петро сказав Йому у відповідь: Господи! Якщо це Ти, звели мені прийти до Тебе по воді.","Він же сказав: прийди. І, вийшовши з човна, Петро пішов по воді, щоб підійти до Ісуса.","Побачивши ж сильний вітер, злякався і, коли почав тонути, закричав: Господи, спаси мене!","Ісус зараз же простяг руку, підтримав його і говорить йому: маловіре! Чого ти засумнівався?","І, як увійшли вони в човен, вітер стих.","Ті, що були в човні, підійшли, вклонилися Йому і сказали: воістину Ти Син Божий.","Переправившись, вони прибули в землю Генісаретську.","Жителі того міста, впізнавши Його, дали знати по всій тій околиці, і принесли до Нього всіх недужих,","і благали Його, щоб тільки доторкнутися до краю одежі Його; і ті, що доторкалися, зцілялися."],"x":{"1":"51.6.14|52.9.7","3":"51.6.17|52.3.19","13":"51.6.32|52.9.10","17":"51.6.38|52.9.13|53.6.9","23":"51.6.46|53.6.15"}},{"v":["Тоді приступають до Ісуса єрусалимські книжники та фарисеї і говорять:","чому ученики Твої порушують передання старців? Бо не миють рук своїх, коли їдять хліб.","Він же сказав їм у відповідь: чому і ви порушуєте заповідь Божу, заради передання вашого?","Бо Бог заповідав: шануй батька й матір; і хто лихословить на батька чи матір, нехай смертю помре.","А ви говорите: якщо хто скаже батькові або матері: дар Богові те, чим би ти від мене скористався,","той може і не шанувати батька свого або матір свою. Таким чином, і ви порушили заповідь Божу переданням вашим.","Лицеміри! Добре пророкував про вас Ісая, кажучи:","наближаються до Мене люди ці устами своїми, й устами шанують Мене, серце ж їхнє далеко від Мене;","але марно шанують Мене, навчаючи вченням і заповідям людським.","І, покликавши людей, сказав їм: слухайте і розумійте!","Не те, що входить в уста, оскверняє людину, а те, що виходить з уст, оскверняє людину.","Тоді ученики Його, приступивши, сказали Йому: чи знаєш, що фарисеї, почувши це слово, спокусилися?","Він же сказав у відповідь: усяка рослина, яку не насадив Отець Мій Небесний, викоріниться.","Облиште їх: вони — сліпі вожді сліпців, а коли сліпець веде сліпця, то обидва впадуть в яму.","Петро ж, відповідаючи, сказав Йому: поясни нам притчу цю.","Ісус сказав: невже і ви ще не розумієте?","Чи ще не зрозуміли, що все, що входить в уста, проходить у черево і виходить геть?","А те, що з уст виходить, від серця виходить; це і оскверняє людину,","бо від серця виходять злі помисли, вбивства, перелюбства, любодіяння, злодійство, лжесвідчення, хула.","Це те, що оскверняє людину, а немитими руками їсти — не оскверняє людину.","І, вийшовши звідти, Ісус пішов у землі Тирські і Сидонські.","І ось жінка-хананеянка, вийшовши з тих місць, закричала Йому: помилуй мене, Господи, Сину Давидів, дочка моя тяжко біснується.","Але Він не відповідав їй ні слова. І підійшли ученики Його і благали Його: відпусти її, бо кричить нам услід.","Він же сказав у відповідь: Я посланий лише до загиблих овець дому Ізраїлевого.","А вона, підійшовши, вклонилася Йому і каже: Господи, допоможи мені.","Він же сказав у відповідь: недобре взяти хліб у дітей і кинути псам.","Вона сказала: так, Господи! Але і пси їдять крихти, що падають зі столу господарів їхніх.","Тоді Ісус сказав їй у відповідь: о жінко! Велика віра твоя; нехай буде тобі, як ти хочеш. І зцілилася дочка її у ту ж мить.","Ісус пішов звідти і прийшов до моря Галилейського, і, зійшовши на гору, сів там.","І приступило до Нього багато народу, маючи з собою кривих, сліпих, німих, калік і багато інших, і клали їх до ніг Ісусових; і Він зцілив їх.","І народ дивувався, бачачи, що німі говорять, каліки стають здоровими, криві ходять і сліпі бачать, і славив Бога Ізраїлевого.","Ісус же, покликавши учеників Своїх, сказав їм: шкода Мені людей, що вже три дні перебувають зі Мною і нічого їм їсти; відпустити ж їх голодними не хочу, щоб не ослабли в дорозі.","Говорять Йому ученики Його: де ж нам у пустелі взяти стільки хліба, щоб нагодувати стільки народу?","Говорить їм Ісус: скільки у вас хлібів? Вони сказали: сім, і трохи риби.","Тоді звелів народові возлягти на землю.","І, взявши сім хлібів та рибу і віддавши хвалу, переломив і дав ученикам Своїм, а ученики — народові.","І їли всі і наситились; і набрали сім повних кошиків залишків,","а тих, що їли, було чотири тисячі чоловіків, не рахуючи жінок та дітей.","І, відпустивши народ, Він сів у човен і прибув у межі Магдалинські."],"x":{"1":"51.7.1","4":"1.20.12|1.21.17|2.20.9|4.5.16|26.20.20|30.3.7|51.7.10|66.6.2","8":"51.7.6","9":"31.29.13","10":"51.7.14","13":"53.15.2","14":"31.42.19|32.5.31|52.6.39","18":"55.3.6","19":"0.6.5|0.8.21|51.7.21","21":"51.7.24","24":"31.58.6|32.50.6|36.34.5-6|50.10.6","30":"31.35.5-6","32":"51.8.1"}},{"v":["І приступили до Нього фарисеї і саддукеї і, спокушаючи Його, просили показати їм знамення з неба.","Він же сказав їм у відповідь: увечері ви говорите: буде погода, бо небо червоне;","А вранці: сьогодні негода, бо небо багряне. Лицеміри! Розпізнавати лице неба ви вмієте, а знамення часу не можете.","Рід лукавий і перелюбний знамення шукає, і знамення не дасться йому, крім знамення Іони пророка. І, залишивши їх, відійшов.","Переправившись на той бік, ученики Його забули взяти хлібів.","Ісус сказав їм: пильнуйте і стережіться закваски фарисейської та саддукейської.","Вони ж розмірковували над цим і говорили: ми ж хлібів не взяли.","Зрозумівши те, Ісус сказав їм: що помишляєте про себе, маловіри, що хлібів не взяли?","Хіба ще не розумієте і не пам’ятаєте про п’ять хлібів на п’ять тисяч, і скільки кошиків ви зібрали?","Ані про сім хлібів на чотири тисячі, і скільки кошиків ви зібрали?","Як не розумієте, що не про хліб сказав Я вам: стережіться закваски фарисейської та саддукейської?","Тоді вони зрозуміли, що Він говорив їм стерегтися не хлібної закваски, а вчення фарисейського та саддукейського.","Коли Ісус прийшов у землі Кесарії Филипової, то спитав учеників Своїх: за кого люди вважають Мене, Сина Людського?","Вони відповіли: одні — за Іоана Хрестителя, другі — за Іллю, інші — за Єремію або за одного з пророків.","Він говорить їм: а ви за кого Мене вважаєте?","Симон же Петро, відповідаючи, сказав: Ти є Христос, Син Бога Живого.","Тоді Ісус сказав йому у відповідь: блажен ти, Симоне, сину Іонин, бо не плоть і не кров* відкрили тобі це, а Отець Мій, Який на небесах;","і Я кажу тобі: ти Петро*, тобто «камінь», і на цьому камені Я збудую Церкву Мою, і врата пекла не здолають її.","І дам тобі ключі Царства Небесного; і що зв’яжеш на землі, те буде зв’язане на небесах, і що розв’яжеш на землі, те буде розв’язане на небесах.","Тоді Ісус наказав ученикам Своїм, щоб нікому не говорили, що Він є Ісус Христос.","З того часу Ісус почав відкривати Своїм ученикам, що Йому належить іти до Єрусалима і багато постраждати від старійшин і первосвящеників і книжників, і бути вбитим, і на третій день воскреснути.","І, відізвавши Його, Петро почав заперечувати Йому: будь милосердний до Себе, Господи! Нехай не буде цього з Тобою!","Він же, обернувшись, сказав Петрові: відійди від Мене, сатано! Ти спокуса Мені, бо думаєш не про Боже, а про людське.","Тоді Ісус сказав ученикам Своїм: якщо хто хоче йти за Мною, нехай зречеться себе, і візьме хрест свій, та йде за Мною.","Бо хто хоче душу* свою зберегти, той погубить її, а хто погубить душу свою заради Мене, той збереже її.","Яка бо користь людині, якщо вона здобуде весь світ, а душу свою занапастить? Або що дасть людина взамін за душу свою?","Бо прийде Син Людський у славі Отця Свого з ангелами Своїми і тоді віддасть кожному за ділами його.","Істинно кажу вам: є деякі з тих, що стоять тут, які не зазнають смерти, доки не побачать Сина Людського, що гряде в Царстві Своїм."],"x":{"1":"50.12.38|51.8.11|63.1.22","2":"52.12.54","4":"42.2.1|50.12.39","5":"51.8.14","6":"51.8.15|52.12.1","13":"37.7.13-14|51.8.27|52.9.18","16":"50.14.33|51.8.29|52.9.20|53.6.69","17":"50.11.25:27","18":"52.22.31-32|56.2.4|63.3.11","19":"50.18.18|53.20.23","20":"51.8.30","23":"62.8.7","24":"50.10.38|51.8.34|52.14.27","27":"25.61.13|48.14.5|50.25.31|62.2.6|76.19.14","28":"51.9.1|52.9.27"},"n":{"17":["Плоть і кров — людина."],"18":["Камінь."],"25":["Життя."]}},{"v":["Коли минуло шість днів, Ісус взяв Петра, Якова та Іоана, брата його, і вивів їх на високу гору одних,","і преобразився перед ними: лице Його засяяло, як сонце, одежа ж Його стала білою, як світло.","І ось явилися їм Мойсей та Ілля, які розмовляли з Ним.","При цьому Петро сказав Ісусові: Господи! Добре нам тут бути; коли хочеш, зробимо тут три намети: Тобі один, Мойсеєві один, і один Іллі.","Поки він говорив це, ясна хмара осінила їх, і ось голос з хмари говорить: Цей є Син Мій Улюблений, в Якому Моє благовоління; Його слухайте.","І, почувши, ученики впали ниць і дуже полякались.","Але Ісус підійшов, доторкнувся до них і сказав: встаньте і не бійтеся.","Звівши ж очі свої, вони нікого не побачили, тільки одного Ісуса.","І коли вони сходили з гори, Ісус наказав їм: нікому не говоріть про це видіння, доки Син Людський не воскресне з мертвих.","І спитали Його ученики Його: чому ж книжники говорять, що Іллі належить прийти раніш?","Ісус сказав їм у відповідь: так, Ілля прийде раніш і все приготує;","але кажу вам, що Ілля вже прийшов, і його не впізнали, і зробили з ним, як хотіли. Так і Син Людський має постраждати від них.","Тоді ученики зрозуміли, що він говорив їм про Іоана Хрестителя.","Коли вони прийшли до народу, то підійшов до Нього чоловік і, ставши перед Ним на коліна,","сказав: Господи! Помилуй сина мого; бо він на новий місяць біснується і тяжко страждає, бо часто кидається в огонь і часто у воду.","Я приводив його до учеників Твоїх, та вони не змогли зцілити його.","Ісус же, відповідаючи, сказав: о роде невірний і розбещений! Доки буду з вами, доки терпітиму вас? Приведіть його до Мене сюди.","І заборонив йому Ісус, і біс вийшов з нього; і отрок зцілився у ту ж мить.","Тоді ученики, приступивши до Ісуса на самоті, сказали: чому ми не змогли вигнати його?","Ісус же сказав їм: через невір’я ваше. Бо істинно кажу вам: якщо ви матимете віру як зерно гірчичне і скажете горі цій: перейди звідси туди, і вона перейде; і не буде нічого неможливого для вас.","Цей же рід виганяється тільки молитвою і постом.","Під час перебування їх у Галилеї, Ісус сказав їм: Син Людський буде виданий в руки людям,","і уб’ють Його, і на третій день воскресне. І вони дуже засмутилися.","Коли ж вони прийшли до Капернаума, то підійшли до Петра збирачі дидрахм* і сказали: чи не дасть Учитель ваш дидрахми?","Він говорить: так. І коли увійшов він у дім, то Ісус, випередивши його, сказав: як тобі здається, Симоне, царі землі з кого беруть мито або податки: зі своїх синів чи з чужих?","Петро говорить Йому: з чужих. Ісус сказав йому: отже, сини вільні;","але, щоб нам не спокусити їх, піди до моря, закинь вудку, і першу спійману рибу візьми, відкрий їй рот і знайдеш статир*, візьми його і віддай їм за Мене і за себе."],"x":{"1":"51.9.2|52.9.28","5":"4.18.15|50.3.17|52.3.22","10":"50.11.14|51.9.11","14":"51.9.17|52.9.38","20":"50.21.21|51.9.23|51.11.23|52.17.6","21":"51.9.29","22":"52.9.22|52.24.7"},"n":{"24":["Дві драхми — податок на храм."],"27":["Чотири драхми."]}},{"v":["У той час ученики приступили до Ісуса і кажуть: хто більший у Царстві Небесному?","Ісус, покликавши дитя, поставив його посеред них","і сказав: істинно кажу вам: якщо ви не навернетесь і не будете як діти, не ввійдете у Царство Небесне.","Отже, хто упокориться, як дитя це, той і більший у Царстві Небесному.","І хто прийме одне таке дитя в ім’я Моє, той Мене приймає;","а хто спокусить одного з малих цих, що вірують у Мене, тому краще було б, якби повісили йому жорно млинове на шию і потопили його в морській глибині.","Горе світові від спокус, бо потрібно, щоб прийшли спокуси; але горе такій людині, через яку спокуса приходить.","Якщо рука твоя чи нога твоя спокушає тебе, відсічи її і кинь від себе: краще тобі ввійти в життя без руки чи без ноги, ніж, дві руки і дві ноги маючи, бути вкинутим у вогонь вічний.","Коли око твоє спокушає тебе, вирви його і кинь від себе: краще тобі з одним оком у життя увійти, аніж з двома очима бути вкинутим у геєну вогненну.","Стережіться, щоб ви не зневажили жодного з цих малих: бо кажу вам, що ангели їхні на небесах повсякчас бачать лице Отця Мого Небесного.","Бо Син Людський прийшов знайти і спасти загибле.","Як вам здається, коли буде в якогось чоловіка сто овець, і одна з них заблукає, чи не покине він у горах дев’яносто дев’ять і не піде шукати ту, що заблукала?","І якщо трапиться знайти її, істинно кажу вам, він радіє за неї більше, ніж за дев’яносто дев’ять, що не заблукали.","Так само немає волі Отця вашого Небесного, щоб загинув один з малих цих.","Якщо ж згрішить проти тебе брат твій, піди і викрий його між тобою і ним одним. Якщо послухає тебе, то придбав ти брата твого.","Якщо ж тебе не послухає, візьми з собою ще одного або двох, щоб устами двох чи трьох свідків підтвердилося кожне слово.","Якщо ж не послухає їх, скажи церкві; якщо ж і церкви не послухає, то нехай він буде тобі як язичник і митар.","Істинно кажу вам: що ви зв’яжете на землі, те буде зв’язане на небі, і що розв’яжете на землі, те буде розв’язане на небі.","Істинно також кажу вам: якщо двоє з вас дійдуть згоди на землі просити про всяку річ, то, чого б вони не попросили, буде їм від Отця Мого Небесного;","бо, де двоє чи троє зібрані в ім’я Моє, там Я серед них.","Тоді Петро підійшов до Нього і сказав: Господи, скільки разів прощати брату моєму, який згрішить проти мене? Чи до семи разів?","Ісус говорить йому: не кажу тобі — до семи, але до сімдесяти разів по сім.","Тому Царство Небесне подібне до царя, який захотів порахуватися з рабами своїми;","коли він почав рахуватися, привели до нього одного боржника, який винен був йому десять тисяч талантів*;","а оскільки він не мав чим заплатити, то господар звелів продати його, і жінку його, і дітей, і все, що він мав, і віддати.","Тоді раб той упав і, кланяючись йому, говорив: господарю, потерпи мені, і все тобі віддам.","Господар змилосердився над рабом тим, простив його і борг відпустив йому.","Раб же той, вийшовши, зустрів одного з товаришів своїх, який був винен йому сто динаріїв*, і, схопивши його, душив і казав: віддай мені, що винен.","Тоді товариш його впав до ніг його, благав його і говорив: потерпи мені, і все віддам тобі.","Але той не захотів, а повів і посадив його у в’язницю, доки не віддасть боргу.","Товариші його, побачивши таке, дуже засмутилися і, прийшовши, розповіли своєму господареві все, що сталося.","Тоді господар покликав його і каже: рабе лукавий! Весь той борг я простив тобі, бо ти ублагав мене.","Чи не належало й тобі помилувати товариша твого, як і я помилував тебе?","І, розгнівавшись, господар віддав його мучителям, доки не віддасть йому всього боргу.","Так і Отець Мій Небесний учинить з вами, якщо кожен з вас не простить від серця свого братові своєму провини його."],"x":{"2":"51.9.36","4":"51.10.14|63.14.20","6":"51.9.42|52.17.1","7":"63.11.19","8":"51.9.43","9":"4.13.6-8|50.5.29","10":"0.19.16|25.33.8|75.1.14","11":"50.10.6|52.9.56","12":"52.15.4","15":"2.19.17|52.17.3|55.5.19-20","16":"4.17.6|4.19.15|53.8.17|64.13.1|75.10.28","18":"50.16.19|53.20.23","21":"52.17.4"},"n":{"24":["Талант — злиток золота чи срібла на велику суму грошей."],"28":["Динарій — срібна римська монета."]}},{"v":["Коли Ісус скінчив слова ці, то вийшов з Галилеї і прийшов у землі Юдейські, що за Йорданом.","За Ним пішло багато людей, і Він зцілив їх там.","І приступили до Нього фарисеї і, спокушаючи Його, говорили Йому: чи за всяку провину дозволено чоловікові розводитися з жінкою своєю?","Він сказав їм у відповідь: чи не читали ви, що Той, Хто створив на початку, чоловіком і жінкою створив їх?","І сказав: заради цього залишить чоловік батька свого й матір і з’єднається з жінкою своєю, і будуть обоє однією плоттю.","Тож вони вже не двоє, але одна плоть. Отже, що Бог з’єднав, того людина нехай не розлучає.","Вони кажуть Йому: чому ж Мойсей заповідав дати розвідний лист і відпустити її?","Він говорить їм: Мойсей через жорстокість серця вашого дозволив вам розводитися з жінками вашими; а спочатку не було так.","Я ж кажу вам: хто розведеться з жінкою своєю, за винятком вини перелюбу, і візьме шлюб з іншою, той перелюбствує; і хто одружиться з відпущеною, той чинить перелюб.","Ученики Його говорять Йому: якщо така повинність чоловіка перед жінкою, то краще не женитись.","Він каже їм: не всі сприймають це слово, а кому дано.","Бо є скопці, що з утроби матері народилися такими; і є скопці, які оскоплені людьми; і є скопці, котрі самі себе зробили скопцями заради Царства Небесного. Хто може вмістити, нехай вмістить.","Тоді привели до Нього дітей, щоб Він поклав на них руки і помолився, ученики ж не дозволяли їм.","Але Ісус сказав: облиште дітей і не забороняйте їм приходити до Мене, бо таких є Царство Небесне.","І, поклавши на них руки, пішов звідти.","І ось хтось, підійшовши, сказав Йому: Учителю Благий, що зробити мені доброго, щоб мати життя вічне?","Він же сказав йому: чому ти називаєш Мене благим? Ніхто не благий, тільки один Бог. Якщо ж хочеш увійти в життя вічне, дотримуйся заповідей.","Говорить Йому: яких? Ісус же сказав: не вбивай; не чини перелюбу; не кради; не лжесвідчи;","шануй батька й матір; і люби ближнього твого, як самого себе.","Юнак говорить Йому: все це я зберіг від юности моєї; чого ще не вистачає мені?","Ісус сказав йому: коли хочеш бути досконалим, піди продай добро твоє і роздай убогим; і матимеш скарб на небесах; і приходь та йди слідом за Мною.","Почувши слово те, юнак відійшов у скорботі, бо мав багато добра.","Ісус же сказав ученикам Своїм: істинно кажу вам, що тяжко багатому ввійти у Царство Небесне.","І ще кажу вам: легше верблюдові пройти крізь вушко голки, ніж багатому в Царство Боже ввійти.","Почувши це, ученики Його дуже здивувались і сказали: так хто ж може спастися?","Ісус, поглянувши, сказав їм: людям це неможливо, Богові ж усе можливо.","Тоді Петро, відповідаючи, сказав Йому: ось ми залишили все і пішли слідом за Тобою, що ж нам буде?","Ісус же сказав їм: істинно говорю вам, що ви, які пішли за Мною, при відновленні світу, коли Син Людський сяде на престолі слави Своєї, сядете і ви на дванадцяти престолах судити дванадцять колін Ізраїлевих.","І всякий, хто залишить дім, або братів, або сестер, або батька, або матір, або жінку, або дітей, або землі заради імені Мого, одержить у стократ і успадкує життя вічне.","І багато хто з перших будуть останніми, а останні — першими."],"x":{"1":"51.10.1","4":"0.1.27|51.10.6","5":"0.2.24|51.10.7-8|63.6.16|66.5.31","7":"4.24.1-4|50.5.31","9":"50.5.32|51.10.11|52.16.18","12":"31.56.3|63.7.7","13":"51.10.13|52.18.15","14":"50.18.3","16":"51.10.17|52.18.18","17":"55.1.17","19":"1.20.12-16|2.19.18|4.5.16-20","26":"24.42.2","27":"51.10.28|52.18.28","28":"52.22.30","30":"51.10.31|52.13.30"}},{"v":["Царство Небесне подібне до господаря дому, який вийшов рано вранці наймати робітників для свого виноградника.","І, домовившись з робітниками по динарію за день, послав їх до свого виноградника.","А коли вийшов він близько третьої години, то побачив інших, що стояли на торгу без діла.","І сказав їм: ідіть і ви до мого виноградника, і, що належатиме, дам вам. Вони пішли.","А як вийшов він знову близько шостої і дев’ятої години, зробив так само.","Нарешті, вийшовши об одинадцятій годині, він знайшов інших, що стояли без діла, і говорить їм: чого тут стоїте цілий день без діла?","Вони кажуть йому: ніхто нас не найняв. Він говорить їм: ідіть і ви до виноградника мого і, що належатиме, одержите.","Коли ж настав вечір, господар виноградника говорить управителеві своєму: поклич робітників і віддай їм плату, почавши з останніх і до перших.","І ті, що прийшли об одинадцятій годині, одержали по динарію.","Ті ж, які прийшли першими, гадали, що вони одержать більше, але й вони одержали по динарію.","І, одержавши, стали дорікати господареві","і говорили: ці останні попрацювали одну годину, і ти зрівняв їх з нами, що перетерпіли денний тягар і спеку.","Він же сказав у відповідь одному з них: друже, я не скривдив тебе; чи не за динарій ти домовився зі мною?","Візьми своє та йди. Я ж хочу і цьому останньому дати те ж, що і тобі.","Хіба я не вільний по-своєму робити те, що хочу? Чи око твоє заздрісне через те, що я добрий?","Так будуть останні першими, і перші — останніми; бо багато покликаних, та мало обраних.","Ідучи до Єрусалима, Ісус узяв дванадцять учеників окремо, і дорогою сказав їм:","ось ми йдемо до Єрусалима, і Син Людський буде виданий первосвященикам і книжникам, і вони засудять Його на смерть;","і віддадуть Його язичникам на ганьбу, і побиття, і розп’яття; і на третій день воскресне.","Тоді підійшла до Нього мати синів Зеведеєвих з синами своїми і, вклоняючись, просила чогось у Нього.","Він сказав їй: чого ти хочеш? Вона говорить Йому: скажи, щоб ці два сини мої сіли в Тебе один з правого боку, а другий з лівого у Царстві Твоїм.","Ісус сказав у відповідь: не знаєте, чого просите. Чи можете пити чашу, яку Я маю пити, і хреститись хрещенням, яким Я хрещуся? Вони кажуть Йому: можемо.","І говорить їм: чашу Мою будете пити, і хрещенням, яким Я хрещусь, будете хреститися; а дати сісти від Мене праворуч і ліворуч — не від Мене залежить, а кому уготоване Отцем Моїм.","Почувши це, інші десять учеників обурились на обох братів.","Ісус же, підізвавши їх, сказав: ви знаєте, що князі народів панують над ними, і вельможі володіють ними.","Не так буде у вас: але хто хоче між вами бути більшим, нехай буде вам слугою.","І хто хоче між вами бути першим, нехай буде вам рабом.","Так само Син Людський не для того прийшов, щоб Йому служили, а щоб послужити і віддати душу Свою на спасіння багатьох.","І коли виходили вони з Єрихона, за Ним ішло багато народу.","І ось двоє сліпих, що сиділи при дорозі, почувши, що Ісус наближається, почали кричати: помилуй нас, Господи, Сину Давидів!","Народ же примушував їх мовчати; але вони ще голосніше почали кричати: помилуй нас, Господи, Сину Давидів!","Ісус, зупинившись, підізвав їх і сказав: що хочете, щоб Я зробив вам?","Вони говорять Йому: Господи, щоб відкрились очі наші.","Ісус же, змилосердившись, доторкнувся до їхніх очей; і в ту ж мить прозріли очі їхні, і вони пішли за Ним."],"x":{"1":"50.21.33","16":"50.19.30|50.22.14","18":"51.10.33|52.18.31","19":"51.10.34|53.18.31-32","20":"51.10.35","22":"50.26.39:42","24":"51.10.41|52.22.24","28":"50.26.28|53.11.51|67.2.7-8","29":"51.10.46|52.18.35","30":"50.9.27"}},{"v":["І коли наблизились до Єрусалима і прийшли у Виффагію до гори Елеонської, тоді Ісус послав двох учеників","і сказав їм: підіть у село, що прямо перед вами, і зразу знайдете прив’язану ослицю і з нею осля; відв’яжіть і приведіть до Мене.","І якщо хто скаже вам що-небудь, відповідайте, що вони потрібні Господеві; і одразу ж відішле їх.","Усе ж це було, щоб збулося сказане пророком, який говорить:","скажіть дочці Сионовій: ось Цар твій гряде до тебе лагідний, сидячи на ослиці й осляті, синові під’яремної.","Ученики пішли і зробили так, як сказав їм Ісус:","привели ослицю й осля і поклали на них одяг свій, і Він сів поверх нього.","Безліч людей розстилали одяг свій по дорозі, а інші різали гілки з дерев і стелили по дорозі.","Люди ж, що йшли попереду і слідом, виголошували: осанна* Синові Давидовому! Благословен, Хто йде в ім’я Господнє! Осанна у вишніх!","І коли увійшов Він у Єрусалим, все місто заворушилось і заговорило: Хто це такий?","Народ же говорив: Цей є Ісус, Пророк із Назарета галилейського.","І увійшов Ісус у храм Божий і вигнав усіх, що продавали і купували в храмі, і поперевертав столи міняйл і лави тих, що продавали голубів.","І сказав їм: дім Мій домом молитви назветься; а ви зробили його вертепом розбійників.","І приступили до Нього в храмі сліпі й криві, і Він зцілив їх.","А первосвященики і книжники, побачивши чудеса, які Він створив, і дітей, які виголошували в храмі: осанна Синові Давидовому, обурились","і сказали Йому: чи чуєш, що вони говорять? Ісус відповів їм: так, невже ви ніколи не читали: з уст немовлят і дітей Ти створив хвалу?","І, залишивши їх, вийшов геть з міста у Вифанію і пробув там ніч.","Вранці ж, повертаючись у місто, зголоднів.","Побачивши біля дороги одну смоковницю, підійшов до неї і, нічого не знайшовши на ній, крім самого листя, говорить їй: нехай не буде надалі від тебе плоду повік. І смоковниця відразу всохла.","Побачивши це, ученики здивувались і говорили: як це — відразу ж всохла смоковниця?","Ісус же сказав їм у відповідь: істинно кажу вам, якщо будете мати віру і не засумніваєтеся, то не тільки зробите те, що сталося із смоковницею, але, якщо і горі цій скажете: піднімись і кинься в море, буде;","і все, чого не попросите в молитві з вірою, одержите.","І коли Він прийшов у храм і навчав, приступили до Нього первосвященики і старійшини народу і сказали: якою владою Ти це робиш? І хто Тобі дав таку владу?","Ісус сказав їм у відповідь: запитаю і Я вас про одне, коли про те скажете Мені, то і Я вам скажу, якою владою це роблю.","Хрещення Іоанове звідки було: з небес чи від людей? Вони ж міркували між собою: якщо скажемо, що з небес, то Він скаже нам: чому ж ви не повірили йому?","А якщо сказати, що від людей, то боїмось народу, бо всі мають Іоана за пророка.","І відповіли Ісусові: не знаємо. Сказав їм і Він: і Я вам не скажу, якою владою це роблю.","А як вам здається? В одного чоловіка було два сини; і він, підійшовши до першого, сказав: сину, піди сьогодні попрацюй у винограднику моєму.","Але той сказав у відповідь: не хочу. Але згодом, розкаявшись, пішов.","І, підійшовши до другого, він сказав те саме. Цей сказав у відповідь: іду, господарю, — та не пішов.","Котрий з цих двох виконав волю батька? Кажуть Йому: перший. Ісус говорить їм: істинно кажу вам, що митарі і блудниці поперед вас йдуть у Царство Боже.","Бо прийшов до вас Іоан Хреститель дорогою праведности, і ви не повірили йому, а митарі та блудниці повірили йому; ви ж, і бачивши це, не розкаялися і потім, щоб повірити йому.","Вислухайте іншу притчу. Був якийсь господар дому, який посадив виноградник і обніс його огорожею, викопав у ньому виностік, збудував башту і, віддавши його виноградарям, від’їхав.","Коли ж наблизився час плодів, він послав своїх слуг до виноградарів узяти свої плоди.","Виноградарі, схопивши слуг його, кого побили, кого вбили, а кого побили камінням.","Знову послав він інших слуг, більше, ніж перше; і з ними зробили так само.","Наостанок послав він до них свого сина, кажучи: посоромляться сина мого.","Але виноградарі, побачивши сина, сказали один одному: це спадкоємець, ходімо уб’ємо його і заволодіємо спадщиною його.","І, схопивши його, вивели геть з виноградника і вбили.","Отже, коли прийде господар виноградника, що він зробить з цими виноградарями?","Говорять Йому: злочинців цих покарає смертю, а виноградник віддасть іншим виноградарям, які віддаватимуть йому плоди своєчасно.","Ісус говорить їм: невже ви ніколи не читали в Писанні: камінь, який відкинули будівничі, той самий став наріжним каменем? Це від Господа, і дивне в очах наших.","Тому кажу вам, що відбереться від вас Царство Боже і дане буде народові, який буде приносити плоди його.","І той, хто впаде на камінь цей, розіб’ється, а на кого він упаде, того розчавить.","І, слухаючи притчі Його, первосвященики і фарисеї зрозуміли, що Він про них говорить.","І шукали нагоди схопити Його, але побоялися народу, бо Його мали за Пророка."],"x":{"1":"51.11.1|52.19.29","5":"31.62.11|48.9.9|53.12.15","7":"51.11.7","8":"53.12.13","9":"25.117.26|51.11.10|52.19.38","12":"51.11.15|52.19.45|53.2.14","13":"31.56.7|32.7.11|51.11.17|52.19.46","16":"25.8.3","19":"51.11.13","21":"50.17.20|52.17.6|55.1.6","22":"50.7.7|51.11.24|53.14.13","23":"50.7.29|51.11.28|52.20.1-2","26":"50.14.5|51.6.20","31":"52.7.29","32":"52.3.12","33":"25.79.9|28.8.11-12|31.5.1|32.2.21|51.12.1|52.20.9","35":"50.5.12|50.23.34:37","38":"50.26.4|50.27.1","39":"75.13.12","42":"25.117.22-23|31.28.16|51.12.10|52.20.17|54.4.11","44":"31.8.14|37.2.44-45|56.2.7|62.9.32"},"n":{"9":["Спасіння."]}},{"v":["Ісус, продовжуючи говорити їм притчами, сказав:","Царство Небесне подібне до чоловіка-царя, який справляв весілля синові своєму.","І послав рабів своїх покликати запрошених на весілля; і не схотіли прийти.","Знову послав інших рабів, говорячи: скажіть званим: ось я приготував мій обід, телят моїх і, що відгодоване, заколоте, і все готове; приходьте на весілля.","Але вони, знехтувавши те, пішли, хто на своє поле, а хто на свої торги.","Інші ж, схопивши рабів його, скривдили і вбили їх.","Почувши про це, цар розгнівався і, пославши військо своє, винищив тих убивць і спалив місто їхнє.","Тоді говорить він рабам своїм: весілля готове, а покликані не були достойні.","Отже, ідіть на роздоріжжя і всіх, кого знайдете, кличте на весілля.","І раби ті, вийшовши на дороги, зібрали всіх, кого тільки знайшли, і злих і добрих; і весілля наповнилося гістьми.","Цар, увійшовши подивитись на гостей, побачив там чоловіка, вбраного не у весільний одяг.","І каже йому: друже, чому ти ввійшов сюди, не маючи весільного одягу? Він же мовчав.","Тоді цар сказав слугам: зв’язавши йому руки і ноги, візьміть його і киньте у пітьму непроглядну: там буде плач і скрегіт зубів.","Бо багато покликаних, та мало обраних.","Тоді фарисеї пішли і радились, як би впіймати Його на слові.","І посилають до Нього своїх учнів з іродіанами, кажучи: Учителю! Ми знаємо, що Ти справедливий і істинно путі Божої вчиш, і не прагнеш будь-кому догодити, бо не зважаєш ні на яку особу.","Отже, скажи нам, як Тобі здається, чи годиться платити подать кесареві, чи ні?","Ісус же, знаючи їхнє лукавство, сказав: чого спокушаєте Мене, лицеміри?","Покажіть Мені монету, якою платиться податок. Вони принесли Йому динарій.","І говорить їм: чиє це зображення і напис?","Кажуть Йому: кесаря. Тоді говорить їм: отже, віддавайте кесареве кесареві, а Боже — Богові.","Почувши це, вони здивувалися і, залишивши Його, відійшли.","В той день приступили до Нього саддукеї, які говорять, що не існує воскресіння, і запитали Його:","Учителю! Мойсей сказав: коли хто помре, не маючи дітей, то брат його нехай візьме жінку його і відродить потомство брата свого.","Було в нас сім братів; перший, одружившись, помер і, не маючи дітей, лишив жінку свою братові своєму.","Так само і другий, і третій, навіть до сьомого.","А після всіх померла і жінка.","Отже, після воскресіння, котрого з семи буде вона жінкою? Бо всі мали її.","Ісус сказав їм у відповідь: помиляєтесь, не знаючи ні Писання, ні сили Божої.","Бо після воскресіння не женяться, не виходять заміж, а перебувають як ангели Божі на небесах.","А про воскресіння мертвих, невже не читали ви сказаного вам Богом:","Я Бог Авраама, і Бог Ісаака, і Бог Якова. Бог не є Бог мертвих, а живих.","І, чуючи, народ дивувався вченню Його.","А фарисеї, почувши, що Він посоромив саддукеїв, зібралися разом.","І один з них, законник, спокушаючи Його, запитав, кажучи:","Учителю, яка заповідь найбільша в законі?","Ісус сказав йому: полюби Господа Бога твого всім серцем твоїм, і всією душею твоєю, і всією думкою твоєю.","Це є перша і найбільша заповідь.","Друга ж подібна до неї: люби ближнього твого, як самого себе.","На цих двох заповідях утверджується весь Закон і Пророки.","Коли зібралися фарисеї, Ісус спитав їх:","що ви думаєте про Христа, чий Він Син? Кажуть Йому: Давидів.","Говорить їм: то як же Давид, у Дусі Божому, зве Його Господом, кажучи:","сказав Господь Господеві моєму: сиди праворуч Мене, доки покладу ворогів Твоїх підніжжям ніг Твоїх.","Отже, якщо Давид зве Його Господом, то як же Він син йому?","І ніхто не зміг відповісти Йому ні слова; і з того дня ніхто вже не смів запитувати Його."],"x":{"2":"26.9.1-2|52.14.16|76.19.7","7":"52.19.27","14":"50.20.16","15":"51.12.13|52.20.20","21":"51.12.17|62.13.7","23":"51.12.18|52.20.27|54.23.8","24":"4.25.5|51.12.19|52.20.28","30":"63.15.44","32":"1.3.6|51.12.26|52.20.37","35":"51.12.28|52.10.25","37":"4.6.5|43.6.8|51.12.30|52.10.27","39":"2.19.18|50.5.43|51.12.31","42":"51.12.35|52.20.41","44":"25.109.1|52.20.42"}},{"v":["Тоді Ісус промовив до народу і учеників Своїх,","кажучи: на Мойсеєвому сидінні сіли книжники та фарисеї.","Отже, все, що кажуть вам додержувати, додержуйте і робіть; а за ділами їхніми не робіть, бо вони говорять і не роблять.","Зв’язують важкі тягарі, які неможливо носити, і кладуть їх людям на плечі; самі ж і пальцем своїм не хочуть зрушити їх.","Всі ж діла свої роблять так, щоб їх бачили люди: розширюють пов’язки* свої і подовжують край одежі своєї.","Також люблять возлежати на перших місцях на вечерях і сидіти на перших місцях у синагогах;","і вітання на торжищах, та щоб люди звали їх: учителю, учителю!","Ви ж не називайтесь учителями, бо один у вас Учитель — Христос; усі ж ви — браття.","І отцем не називайте собі нікого на землі, бо один у вас Отець, Який на небесах.","І не називайтесь наставниками, бо один у вас Наставник — Христос.","Більший же з вас нехай буде вам слугою.","Бо хто підносить себе, той принижений буде, а хто понижує себе, той піднесеться.","Горе вам, книжники і фарисеї, лицеміри, що зачиняєте Царство Небесне перед людьми, бо ви і самі не входите, і тим, хто входить, не даєте увійти.","Горе вам, книжники і фарисеї, лицеміри, що поїдаєте доми вдовиць, напоказ довго молитесь: за те ще більший осуд приймете.","Горе вам, книжники і фарисеї, лицеміри, що обходите море і сушу, щоб навернути хоч одного; і коли це станеться, робите його сином геєни, удвічі гіршим за вас.","Горе вам, вожді сліпі, які говорять: якщо хто поклянеться храмом, то нічого, а якщо хто поклянеться золотом храму, той винний.","Безумні і сліпі! Що більше: золото чи храм, який освячує золото?","І ще, коли хто поклянеться жертовником, то нічого, а якщо хто поклянеться даром, що на ньому, той винний.","Безумні і сліпі! Що більше: дар чи жертовник, який освячує дар?","Отже, хто клянеться жертовником, клянеться ним і всім, що на ньому.","І хто клянеться храмом, клянеться ним і Тим, Хто живе в ньому.","І хто клянеться небом, клянеться Престолом Божим і Тим, Хто сидить на ньому.","Горе вам, книжники і фарисеї, лицеміри, що даєте десятину* з м’яти, кропу і кмину, а облишили те, що є найважливіше в законі: суд, милість і віру; це належало робити, і того не залишати.","Вожді сліпі, що відціджуєте комара, а верблюда поглинаєте!","Горе вам, книжники і фарисеї, лицеміри, що очищаєте зовні чаші і блюда, тоді як усередині вони повні злодійства і неправди.","Фарисею сліпий, очисть перше всередині чаші і блюда, щоб чистими були і зовні вони.","Горе вам, книжники і фарисеї, лицеміри, що уподібнюєтесь розмальованим гробам, які зовні здаються гарними, а всередині повні кісток мертвих і всякої нечистоти.","Так і ви на вигляд здаєтесь людям праведними, а всередині повні лицемірства і беззаконня.","Горе вам, книжники і фарисеї, лицеміри, що будуєте гробниці пророкам і оздоблюєте пам’ятники праведникам,","і говорите: якби ми були у дні батьків наших, то не були б спільниками їхніми у проливанні крови пророків.","Тим ви самі свідчите проти себе, що ви сини тих, які вбивали пророків.","І ви доповнюєте міру зла батьків ваших.","Змії, поріддя єхиднове! Як утечете ви від суду вогню геєнського?","Тому ось Я посилаю до вас пророків, і мудрих, і книжників. І ви одних уб’єте і розіпнете, а інших будете бити в синагогах ваших і гнати з міста до міста.","Нехай прийде на вас уся кров праведна, пролита на землі, від крови Авеля праведного до крови Захарії, сина Варахії, якого вбили між храмом і жертовником.","Істинно кажу вам, що все це прийде на рід цей.","Єрусалиме, Єрусалиме, що вбиваєш пророків і камінням побиваєш посланих до тебе! Скільки разів хотів Я зібрати дітей твоїх, як птах збирає пташенят своїх під крила, і ви не схотіли!","Ось лишається вам дім ваш пустий.","Бо кажу вам: не побачите Мене віднині, доки не скажете: благословен, Хто йде в ім’я Господнє!"],"x":{"4":"52.11.46|54.15.10","5":"3.15.38|4.22.12","6":"51.12.39|52.11.43|52.20.46","8":"55.3.1|63.3.4","9":"49.1.6","12":"52.14.11","13":"36.22.26|52.11.52","14":"51.12.40|52.20.47","19":"1.29.37","21":"13.6.2|25.25.8","23":"38.6.6|43.6.8|50.12.7|52.11.42","27":"52.11.44|54.23.3","33":"50.3.7","34":"13.36.15-16|52.11.49","35":"0.4.8|13.24.21-22|52.11.51|58.3.12","37":"4.32.11-12|52.13.34","38":"52.13.35","39":"25.117.26|50.21.9"},"n":{"5":["Пов’язки на чолі і на руках зі словами із закону."],"23":["Десяту частину."]}},{"v":["І, вийшовши, Ісус пішов від храму; і підійшли до Нього ученики Його, щоб показати Йому будівлі храму.","Ісус же сказав їм: чи бачите все це? Істинно кажу вам: не залишиться тут каменя на камені, все буде зруйновано.","Коли ж сидів Він на горі Елеонській, то приступили до Нього ученики на самоті і спитали: скажи нам, коли це буде і яке знамення Твого пришестя і кінця віку?","Ісус сказав їм у відповідь: стережіться, щоб хто не спокусив вас,","бо багато хто прийде під іменем Моїм і казатиме: «я Христос», і багатьох спокусять.","Також почуєте про війни і чутки про війни. Глядіть, не жахайтесь, бо належить усьому тому бути, та це ще не кінець.","Постане бо народ на народ, і царство на царство; і будуть голод, моровиці і землетруси у різних місцях;","усе ж це — лиш початок хвороб.","Тоді видаватимуть вас на муки і вбиватимуть вас; і вас зненавидять усі народи через ім’я Моє.","І тоді багато хто спокуситься, і видаватимуть один одного, і зненавидять один одного;","і багато лжепророків з’явиться і багатьох спокусять;","і через збільшення беззаконь охолоне любов у багатьох.","Хто ж витерпить до кінця, той спасеться.","І буде проповідане це Євангеліє Царства по всьому світу, на свідчення усім народам; і тоді прийде кінець!","Отже, коли побачите мерзоту запустіння, провіщену пророком Даниїлом, яка стоїть на святому місці, — хто читає, нехай розуміє, —","тоді, хто буде в Юдеї, нехай біжить у гори.","І хто на покрівлі, той нехай не сходить взяти що-небудь з дому свого;","і хто на полі, той нехай не вертається взяти одяг свій.","Горе ж вагітним і матерям-годувальницям у ті дні!","Моліться ж, щоб не сталася втеча ваша взимку або в суботу,","бо тоді буде велика скорбота, якої не було від початку світу донині і не буде.","І якби не вкоротилися ті дні, то не спаслась би ніяка плоть; але заради обраних скоротяться ті дні.","Тоді, якщо хто скаже вам: ось тут Христос, або: отам, не йміть віри.","Бо встануть лжехристи і лжепророки і покажуть великі знамення і чудеса, щоб звабити, якщо можливо, і обраних.","Ось Я наперед сказав вам.","Отже, коли скажуть вам: «ось Він у пустелі», — не виходьте; «ось Він у потаємних кімнатах», — не йміть віри.","Бо, як блискавиця виходить зі сходу і з’являється аж до заходу, так буде пришестя Сина Людського.","Бо де буде труп, там зберуться орли.","І враз, після скорботи тих днів, сонце померкне, і місяць не дасть світла свого, і зірки спадуть з неба, і сили небесні захитаються.","І тоді з’явиться знамення Сина Людського на небі; і заплачуть всі племена земні і побачать Сина Людського, Який гряде на хмарах небесних з силою і славою великою.","І пошле ангелів Своїх з сурмою гучноголосою; і зберуть обраних Його від чотирьох вітрів, від краю небес до кінця їх.","Від смоковниці навчіться притчі: коли гілля її стає вже м’яким і пускає листя, то знаєте, що близько літо.","Так само і ви: коли побачите все це, знайте, що близько, при дверях.","Істинно кажу вам: не перейде рід цей, як усе це буде.","Небо і земля перейдуть, слова ж Мої не перейдуть.","Про день же той і годину ніхто не знає, ні ангели небесні, а тільки Отець Мій один.","Але, як було у дні Ноя, так буде і в пришестя Сина Людського;","бо, як у дні перед потопом їли, пили, женились і виходили заміж аж до того дня, як увійшов Ной у ковчег,","і не думали, поки не прийшов потоп і не забрав усіх, — так буде і в пришестя Сина Людського.","Тоді з двох, що будуть у полі, одного буде забрано, а другого залишено;","дві, що мелють на жорнах: одну буде забрано, а другу залишено.","Отже, пильнуйте, бо не знаєте, в яку годину Господь ваш прийде.","Але це ви знайте, що, якби знав господар дому, у яку сторожу прийде злодій, то пильнував би і не дав би підкопати дому свого.","Тому і ви будьте готові, бо в ту годину, про яку й не думаєте, прийде Син Людський.","Хто ж є вірним і мудрим рабом, якого господар його поставить над слугами своїми, щоб давати їм їжу вчасно?","Блажен той раб, господар якого, прийшовши, знайде, що він робить так.","Істинно кажу вам, що над усім добром своїм поставить його.","Якщо ж раб той, будучи злим, скаже в серці своїм: не скоро прийде господар мій,","і почне бити товаришів своїх, їсти й пити з п’яницями, —","то прийде господар раба того в той день, в який він не сподівається, і в годину, про яку не знає.","І розсіче його і визначить йому одну долю з лицемірами; там буде плач і скрегіт зубів."],"x":{"1":"51.13.1|52.21.5","2":"51.13.2|52.19.44|52.21.6","4":"51.13.5|52.21.8|70.2.3","9":"50.10.17|51.13.9|52.21.12|53.15.20","15":"37.9.27|51.13.14|52.21.20","23":"51.13.21|52.17.23","28":"52.17.37","29":"31.13.10|36.32.7|39.2.31|51.13.24|52.21.25","30":"48.12.10|51.14.62|76.1.7","31":"63.15.52|69.4.16","34":"51.13.30-31","35":"31.51.6|57.3.10","37":"0.7.7|52.17.26|56.3.20","42":"50.25.13|51.13.33","43":"52.12.39|69.5.2|76.16.15","45":"52.12.42|63.4.2","46":"76.16.15"}},{"v":["Тоді уподібниться Царство Небесне десятьом дівам, які, взявши світильники свої, вийшли назустріч женихові.","П’ять з них були мудрі, а п’ять — нерозумні.","Нерозумні, взявши світильники свої, не взяли з собою оливи.","Мудрі ж взяли оливи в посудинах разом із світильниками своїми.","А оскільки жених забарився, то всі задрімали і поснули.","Опівночі ж почувся крик: ось жених іде, виходьте назустріч йому.","Тоді встали всі діви та й приготували світильники свої.","Нерозумні ж сказали мудрим: дайте нам вашої оливи, бо світильники наші гаснуть.","А мудрі відповіли, кажучи: а як і нам, і вам не стане? Ідіть краще до продавців та й купіть собі.","Коли ж пішли вони купувати, прийшов жених, і ті, які були готові, ввійшли з ним на весілля, і двері зачинилися.","Пізніше прийшли й інші діви і говорять: Господи! Господи! Відчини нам.","Він же сказав їм у відповідь: істинно кажу вам: не знаю вас.","Отже, пильнуйте, бо не знаєте ні дня, ні години, коли Син Людський прийде.","Так само один чоловік, відходячи, покликав своїх рабів і передав їм майно своє:","одному дав п’ять талантів, другому два, іншому ж один, кожному за спроможністю його, і відразу ж виїхав.","Той раб, який одержав п’ять талантів, пішов і використав їх на діло, і набув інші п’ять талантів.","Так само і той, який одержав два таланти, набув інші два.","А той, який одержав один талант, пішов і закопав його в землю, і заховав срібло господаря свого.","Коли минуло багато часу, приходить господар рабів тих і вимагає від них звіту.","Підійшов той, який одержав п’ять талантів, приніс інші п’ять талантів і сказав: господарю, п’ять талантів ти дав мені; ось ще п’ять талантів, які я здобув на них.","Господар його сказав йому: гаразд, добрий і вірний рабе! У малому ти був вірним, над великим тебе поставлю; увійди в радість господаря твого.","Підійшов також і той, який одержав два таланти, і сказав: господарю, два таланти ти дав мені; ось інші два таланти, що я здобув на них.","Господар його сказав йому: гаразд, добрий і вірний рабе! У малому ти був вірним, над великим тебе поставлю; увійди в радість господаря твого.","Підійшов і той, який одержав один талант, і сказав: господарю! Я знав тебе, як жорстоку людину, жнеш, де не сіяв, і збираєш, де не розсипав;","і, побоявшись, пішов і заховав талант твій у землю; ось тобі твоє.","Господар його сказав йому у відповідь: лукавий рабе і лінивий! Ти знав, що я жну, де не сіяв, і збираю, де не розсипав;","тоді треба було тобі віддати срібло моє купцям, і я, прийшовши, одержав би моє з прибутком.","Отже, візьміть у нього талант і дайте тому, хто має десять талантів.","Бо кожному, хто має, дасться і примножиться, а в того, хто не має, відніметься і те, що має.","А негідного раба вкиньте у пітьму непроглядну: там буде плач і скрегіт зубів. Сказавши це, проголосив: хто має вуха слухати, нехай слухає!","Коли ж прийде Син Людський у славі Своїй і всі святі ангели з Ним, тоді сяде на престолі слави Своєї,","і зберуться перед Ним усі народи; і відділить їх одних від одних, як пастир відділяє овець від козлів.","І поставить овець праворуч Себе, а козлів — ліворуч.","Тоді скаже Цар тим, які праворуч від Нього: прийдіть, благословенні Отця Мого, успадкуйте Царство, уготоване вам від створення світу.","Бо голодував Я, і ви дали Мені їсти; спраглим був, і ви напоїли Мене; був подорожнім, і ви прийняли Мене;","був нагим, і ви зодягли Мене; був недужим, і ви відвідали Мене; у в’язниці був, і ви прийшли до Мене.","Тоді скажуть Йому праведники у відповідь: Господи!","Коли ми бачили Тебе голодним, і нагодували? Або спраглим, і напоїли? Коли ми бачили Тебе подорожнім, і прийняли? Або нагим, і зодягли?","Коли ми бачили Тебе недужим або у в’язниці, і прийшли до Тебе?","І Цар скаже їм у відповідь: істинно кажу вам: зробивши це одному з цих братів Моїх менших, Мені зробили.","Тоді скаже й тим, які ліворуч від Нього: ідіть від Мене, прокляті, у вогонь вічний, уготований дияволу і ангелам його.","Бо голодував Я, і ви не дали Мені їсти; спраглим був, і ви не напоїли Мене;","був подорожнім, і не прийняли Мене; був нагим, і не зодягли Мене; недужим і у в’язниці, і не відвідали Мене.","Тоді й вони скажуть Йому у відповідь: Господи! Коли ж ми бачили Тебе голодним, або спраглим, чи подорожнім, або нагим, або недужим, або у в’язниці і не послужили Тобі?","Тоді скаже їм у відповідь: істинно кажу вам: не зробивши цього одному з менших цих, Мені не зробили.","І підуть ці на вічні муки, а праведники в життя вічне."],"x":{"10":"52.13.25","11":"50.7.21","12":"25.5.5|45.1.13","13":"51.13.33|63.16.13","14":"52.19.12","15":"62.12.6|63.12.7:11","21":"31.61.7","29":"50.13.12|51.4.25|52.8.18|52.19.26","30":"50.24.51","31":"50.13.49|50.16.27|54.1.11","34":"50.20.23","35":"31.58.7|36.18.7|72.1.18","40":"26.14.31|26.19.17","41":"25.6.9|52.13.27","46":"37.12.2|53.5.29"}},{"v":["Коли Ісус скінчив усі ці слова, то сказав ученикам Своїм:","ви знаєте, що через два дні буде Пасха, і Син Людський виданий буде на розп’яття.","Тоді зібралися первосвященики, і книжники, і старійшини народу у дворі первосвященика на ім’я Каяфа,","і радились, щоб узяти Ісуса підступом і вбити.","Але говорили: тільки не у свято, щоб не було заворушення в народі.","Коли ж Ісус був у Вифанії, в домі Симона прокаженого,","підійшла до Нього жінка з посудиною дорогоцінного мира і зливала Йому, що возлежав, на голову.","Побачивши це, ученики Його ремствували і говорили: для чого таке марнотратство?","Бо можна було б це миро продати за велику ціну і роздати вбогим.","Ісус же, зрозумівши це, сказав їм: навіщо бентежите жінку? Вона добре діло зробила для Мене.","Бо вбогих завжди маєте з собою, а Мене не завжди маєте.","Зливши миро це на тіло Моє, до погребіння Мене приготувала.","Істинно кажу вам: де тільки буде проповідане Євангеліє це по всьому світу, сказано буде про те, що вона зробила, в пам’ять її.","Тоді один з дванадцятьох, званий Іудою Іскаріотом, пішов до первосвящеників","і сказав: що хочете дати мені, — і я вам видам Його? Вони запропонували йому тридцять срібників.","І відтоді він шукав нагоди, щоб видати Його.","Першого ж дня опрісноків ученики приступили до Ісуса і сказали Йому: де хочеш, щоб ми приготували Тобі їсти паску?","Він сказав: підіть у місто до такого-то і скажіть йому: Учитель говорить: час Мій близько; у тебе справлю Пасху з учениками Моїми.","Ученики зробили, як звелів їм Ісус, і приготували паску.","Коли ж настав вечір, Він возліг з дванадцятьма учениками.","І коли вони їли, сказав: істинно кажу вам, що один з вас зрадить Мене.","Вони дуже засмутились і почали говорити Йому, кожен з них: чи не я, Господи?","Він же сказав у відповідь: хто вмочить зі Мною руку в блюдо, той зрадить Мене.","Син же Людський іде, як писано про Нього, але горе тій людині, якою Син Людський буде зраджений: краще було б не народитися людині тій.","При цьому Іуда, що зрадив Його, сказав: чи не я, Учителю? Ісус говорить йому: ти сказав.","І коли вони їли, Ісус узяв хліб і, благословивши, переламав і, роздаючи ученикам, сказав: прийміть, споживайте, це є Тіло Моє.","І, взявши чашу та воздавши хвалу, подав їм і сказав: пийте з неї всі,","бо це є Кров Моя Нового Завіту, що за багатьох проливається на відпущення гріхів.","Кажу ж вам, що віднині не буду пити від цього плоду виноградного до того дня, коли питиму з вами його новим у Царстві Отця Мого.","І, проспівавши, пішли на гору Елеонську.","Тоді говорить їм Ісус: всі ви спокуситеся через Мене в цю ніч, бо написано: уражу пастиря, і розбіжаться вівці отари.","По воскресінні ж Моїм випереджу вас у Галилеї.","Петро сказав Йому у відповідь: якщо і всі спокусяться Тобою, то я ніколи не спокушусь.","Ісус сказав йому: істинно кажу тобі, що в цю ніч, перше ніж проспіває півень, ти тричі зречешся Мене.","Говорить Йому Петро: хоч би мені довелось і вмерти з Тобою, не зречуся Тебе. Подібне говорили і всі ученики.","Потім приходить з ними Ісус у місцевість, що зветься Гефсиманією, і говорить ученикам: посидьте тут, поки Я піду та помолюся там.","І, взявши з Собою Петра і обох синів Зеведеєвих, почав сумувати й тужити.","Тоді говорить їм Ісус: сумна душа Моя смертельно; почекайте тут і пильнуйте зі Мною.","І, відійшовши трохи, упав Він долілиць, молився і говорив: Отче Мій! Якщо можливо, нехай обійде Мене чаша ця; втім, не як Я хочу, а як Ти.","І приходить до учеників, і знаходить їх сплячими, і говорить Петрові: то не змогли ви й однієї години попильнувати зі Мною?","Пильнуйте й моліться, щоб не зазнати спокуси: дух бадьорий, плоть же немічна.","Знову відійшовши, вдруге молився, кажучи: Отче Мій! Якщо не може чаша ця обминути Мене, щоб Мені не пити її, нехай буде воля Твоя.","І, прийшовши, знаходить їх знову сплячими, бо в них очі обважніли.","І, залишивши їх, знову відійшов і помолився втретє, сказавши те саме слово.","Тоді приходить до учеників Своїх і говорить їм: ви все ще спите і відпочиваєте; ось наблизився час, і Син Людський видається в руки грішників.","Встаньте, підемо, ось наблизився той, хто зраджує Мене.","І, коли Він ще говорив, ось прийшов Іуда, один з дванадцятьох, і з ним багато народу з мечами та киями, від первосвящеників і старійшин людських.","Зрадник же Його подав їм знак, сказавши: Кого я поцілую, Той і є, беріть Його.","І, відразу ж підійшовши до Ісуса, сказав: радуйся, Учителю! І поцілував Його.","Ісус же сказав йому: друже, для чого ти прийшов? Тоді підійшли, наклали руки на Ісуса і взяли Його.","І ось один з тих, що були з Ісусом, простягнувши руку, вихопив меч свій і, вдаривши раба первосвященика, відсік йому вухо.","Тоді Ісус говорить йому: поверни меч твій на його місце, бо всі, хто візьме меч, від меча і загинуть;","чи думаєш, що Я не можу тепер ублагати Отця Мого, і Він дасть Мені більш як дванадцять легіонів ангелів?","Як же тоді збудуться Писання, що так повинно бути?","Тоді сказав Ісус до народу: ніби на розбійника вийшли ви з мечами та киями, щоб узяти Мене; кожного дня сидів Я з вами, навчаючи в храмі, і ви не брали Мене.","Це ж усе сталося, щоб збулися Писання пророків. Тоді всі ученики, покинувши Його, розбіглися.","А воїни, які взяли Ісуса, повели Його до Каяфи, первосвященика, де зібралися книжники і старійшини.","Петро ж ішов за Ним здаля, до двору первосвященика; і, ввійшовши всередину, сів із слугами, щоб бачити кінець.","Первосвященики і старійшини, і весь синедріон* шукали лжесвідчення проти Ісуса, щоб убити Його,","і не знаходили; і, хоч багато лжесвідків приходило, не знайшли. Але, наостанок, прийшли два лжесвідки","і сказали: Він говорив: можу зруйнувати храм Божий і за три дні збудувати його.","І, вставши, первосвященик сказав Йому: чому ж нічого не відповідаєш, що вони проти Тебе свідчать?","Ісус мовчав. І первосвященик сказав Йому: заклинаю Тебе Богом Живим, скажи нам, чи Ти Христос, Син Божий?","Ісус говорить йому: ти сказав; але скажу вам: віднині побачите Сина Людського, Який сидить праворуч Сили і гряде на хмарах небесних.","Тоді первосвященик роздер одяг свій і сказав: Він богохульствує! Навіщо нам ще свідки? Ось тільки що ви чули хулу Його!","Як вам здається? Вони ж сказали у відповідь: повинен смерті.","Тоді плювали Йому в лице і знущалися з Нього, а деякі били Його по щоках","і говорили: проречи нам, Христе, хто вдарив Тебе?","Петро ж сидів у дворі. І підійшла до нього одна служниця і сказала: і ти був з Ісусом Галилейським.","Він же відрікся перед усіма, кажучи: не знаю, що ти говориш.","Коли ж він виходив за ворота, побачила його інша і говорить тим, що були там: і цей був з Ісусом Назореєм.","І він знову відрікся з клятвою: не знаю Цього Чоловіка.","Трохи згодом підійшли ті, що стояли там, і сказали Петрові: справді і ти з них, бо і мова твоя викриває тебе.","Тоді він почав божитися й клястися, що не знає Цього Чоловіка. І раптом заспівав півень.","І згадав Петро слово, сказане йому Ісусом: перше ніж проспіває півень, тричі зречешся Мене! І, вийшовши геть, плакав гірко."],"x":{"2":"51.14.1|52.22.1|53.13.1","3":"25.2.2|53.11.47","4":"25.40.8","6":"51.14.3|53.11.2|53.12.3","11":"4.15.11","14":"51.14.10|52.22.4","15":"48.11.13","17":"1.12.6:15|51.14.12|52.22.7","20":"52.22.14","21":"25.40.10|51.14.18|53.13.21","24":"25.21.3|31.53.3|37.9.26","26":"51.14.22|52.22.19|63.11.24","28":"50.20.28","31":"48.13.7|51.14.27|53.16.32","32":"50.28.16|51.14.28","34":"51.14.30|52.22.34|53.13.38","36":"51.14.32|52.22.39","37":"25.114.3|53.12.27","39":"50.20.22|53.5.30|67.2.8|75.5.7-8","47":"51.14.43|52.22.47|53.18.3","52":"0.9.6|76.13.10","53":"37.7.10","54":"25.21.2|31.53.2|37.9.26","57":"51.14.53|52.22.54","59":"25.26.12|25.34.11|51.14.55","61":"50.27.40|51.14.58|53.2.19","63":"31.53.7|54.8.33","64":"25.109.1|37.7.13|50.16.27|53.6.62|54.1.11|62.14.11|69.4.16|76.1.7","67":"31.50.6|31.53.3","70":"51.14.68","74":"51.14.72"},"n":{"59":["Найвищий суд у древніх юдеїв."]}},{"v":["Коли ж настав ранок, усі первосвященики і старійшини людські зібрали раду на Ісуса, щоб убити Його.","І, зв’язавши Його, відвели і видали Його Понтію Пилату, правителю.","Тоді Іуда, що зрадив Його, побачивши, що Він засуджений, і розкаявшись, повернув тридцять срібників первосвященикам та старійшинам,","кажучи: згрішив я, зрадивши кров невинну. Вони ж сказали йому: що нам до того? Гляди сам.","І, кинувши срібники в храмі, він вийшов, пішов і удавився.","Первосвященики ж, взявши срібники, сказали: не дозволено класти їх у скарбницю церковну, тому що це ціна крови.","І, скликавши раду, купили за них землю гончареву для погребіння подорожніх.","Тому і зветься земля та «землею крови» до цього дня.","Тоді збулося сказане пророком Єремією, який говорить: і взяли тридцять срібників, ціну Оціненого, Якого оцінили сини Ізраїля,","і дали їх за землю гончареву, як сказав мені Господь.","Ісус же став перед правителем. І питав Його правитель: Ти Цар Юдейський? Ісус сказав йому: ти говориш.","І коли звинувачували Його первосвященики і старійшини, Він нічого не відповідав.","Тоді говорить Йому Пилат: чи не чуєш, скільки свідчать проти Тебе?","І не відповідав йому ні на жодне слово, так що правитель вельми дивувався.","На свято ж Пасхи правитель мав звичай відпускати народові одного в’язня, якого хотіли.","Був тоді у них відомий в’язень, званий Вараввою.","Отже, коли вони зібралися, Пилат сказав їм: кого хочете, щоб я відпустив вам — Варавву чи Ісуса, названого Христом?","Бо знав, що видали Його через заздрощі.","Коли ж він сидів на судилищі, жінка його послала йому сказати: не роби нічого Праведникові Тому, бо я багато потерпіла сьогодні уві сні через Нього.","Але первосвященики і старійшини підмовили народ просити за Варавву, а Ісуса погубити.","Тоді правитель спитав їх: кого з двох хочете, щоб я відпустив вам? Вони сказали: Варавву.","Пилат говорить їм: що ж мені робити з Ісусом, нареченим Христом? Кажуть йому всі: хай буде розіп’ятий.","Правитель сказав: яке ж зло вчинив Він? Та вони ще дужче кричали: нехай буде розіп’ятий.","Пилат, побачивши, що ніщо не допомагає, а заворушення зростає, взяв води, і вмив руки перед народом, і сказав: не винний я в крові Праведника Цього; дивіться ви.","Увесь народ, відповідаючи, сказав: кров Його на нас і на дітях наших.","Тоді відпустив їм Варавву, а Ісуса, бивши, віддав на розп’яття.","Тоді воїни правителя, взявши Ісуса до преторії*, зібрали на Нього багато воїнів","і, роздягнувши Його, наділи на Нього багряницю;","і, сплівши вінець з терну, поклали Йому на голову, і дали Йому в праву руку тростину; і, стаючи перед Ним на коліна, глузували з Нього, кажучи: радуйся, Царю Юдейський!","І плювали на Нього, і, взявши тростину, били Його по голові.","А коли наглумилися з Нього, зняли з Нього багряницю і вдягли Його в одяг Його й повели на розп’яття.","Виходячи, вони зустріли одного чоловіка киринейського на ім’я Симон; і примусили цього нести хрест Його.","І коли прийшли на місце, яке зветься Голгофа, що значить Лобне місце,","дали Йому пити оцет, змішаний з жовчю; і, покуштувавши, не схотів пити.","Ті ж, що розіп’яли Його, поділили одяг Його, кидаючи жереб;","І, сидячи, стерегли Його там.","І поставили над головою Його напис провини Його: Цей є Ісус, Цар Юдейський.","Тоді розіп’яли з Ним двох розбійників: одного праворуч, а другого ліворуч.","Ті, що проходили мимо, лихословили на Нього, киваючи головами своїми","і кажучи: Ти, Який руйнуєш храм і за три дні відбудовуєш, спаси Себе Самого; якщо Ти Син Божий, зійди з хреста.","Так само і первосвященики з книжниками та старійшинами і фарисеями, глузуючи, говорили:","інших спасав, а Себе Самого не може спасти; якщо Він Цар Ізраїлів, нехай тепер зійде з хреста, і ми увіруємо в Нього;","уповав на Бога, нехай тепер порятує Його, якщо Він угодний Йому. Бо Він казав: Я — Син Божий.","Також і розбійники, розіп’яті з Ним, ганьбили Його.","З шостої ж години настала темрява по всій землі до години дев’ятої.","А близько дев’ятої години Ісус викрикнув гучним голосом: Ілі, Ілі! Лама савахфані! Що значить: Боже Мій, Боже Мій! Навіщо Ти Мене покинув?","Деякі з тих, що стояли там, почувши це, говорили: Він кличе Іллю.","І зараз же один з них побіг, взяв губку, намочив оцтом і, настромивши на тростину, давав Йому пити.","А інші говорили: стривайте, побачимо, чи прийде Ілля спасти Його.","Ісус же, знову скрикнувши гучним голосом, віддав дух.","І ось завіса храму роздерлася надвоє, зверху донизу;","і земля потряслась; і каміння порозпадалось; і гроби розкрились; і багато тіл померлих святих воскресли","і, вийшовши з гробів після воскресіння Його, ввійшли у святе місто і явилися багатьом.","Сотник же і ті, що стерегли з ним Ісуса, побачивши землетрус і все, що сталося, злякались дуже і говорили: воістину Він був Син Божий.","Там було також багато жінок, що дивилися здалеку; вони йшли за Ісусом з Галилеї, слугуючи Йому;","між ними були Марія Магдалина і Марія, мати Якова та Іосії, і мати синів Зеведеєвих.","Коли ж настав вечір, прийшов багатий чоловік з Аримафеї на ім’я Йосиф, який також вчився в Ісуса.","Він, прийшовши до Пилата, просив тіло Ісуса. Тоді Пилат звелів віддати тіло.","І, взявши тіло, Йосиф обгорнув чистою плащаницею","і поклав Його в новому своєму гробі, який він витесав у скелі, і, приваливши великий камінь до дверей гробу, відійшов.","Були ж там Марія Магдалина й інша Марія, які сиділи навпроти гробу.","Наступного ранку, що після п’ятниці, зійшлися первосвященики і фарисеї до Пилата","і говорили: правителю! Ми згадали, що той обманщик, коли ще був живий, сказав: через три дні воскресну.","То звели охороняти гріб до третього дня, щоб ученики Його, прийшовши вночі, не вкрали Його і не сказали народові: воскрес з мертвих; і буде останній обман гірше першого.","Пилат сказав їм: маєте сторожу; підіть, охороняйте, як знаєте.","Вони пішли і поставили біля гробу сторожу і наклали на камінь печать."],"x":{"1":"25.2.2","2":"51.15.1|52.23.1","5":"54.1.18","8":"54.1.19","9":"32.32.9|48.11.12","11":"51.15.2|52.23.3|53.18.37|71.6.13","12":"50.26.63","17":"50.21.11","20":"51.15.11|52.23.18|53.18.40|54.3.14","26":"51.15.15|53.19.1","33":"51.15.22|52.23.33|53.19.17|75.13.12","34":"25.68.22","35":"25.21.19","38":"31.53.12","39":"25.21.8|25.108.25","40":"50.26.61|51.14.58","43":"25.21.9:18|29.2.18","45":"40.8.9","46":"25.21.2|51.15.34","48":"25.68.22|53.19.29","51":"1.26.31|13.3.14|75.10.20","57":"51.15.42-43|52.23.50|53.19.38"},"n":{"27":["Судилище преторське."]}},{"v":["Після ж суботнього вечора, на світанку першого дня після суботи, прийшли Марія Магдалина та інша Марія подивитися на гріб.","І ось стався великий землетрус, бо ангел Господній, який зійшов з неба, приступивши, відвалив камінь від дверей гробу і сів на ньому.","Вигляд його був як блискавка, і одежа його біла, як сніг.","Зі страху перед ним ті, що стерегли, затремтіли і стали як мертві;","Ангел же, звернувшись до жінок, сказав: не бійтеся, бо знаю, що ви шукаєте Ісуса розіп’ятого.","Його нема тут — Він воскрес, як сказав. Підійдіть, погляньте на місце, де лежав Господь.","І підіть швидше, скажіть ученикам Його, що Він воскрес з мертвих і попередить вас у Галилеї; там Його побачите. Ось я сказав вам.","І, вийшовши поспішно з гробу, вони зі страхом і великою радістю побігли сповістити учеників Його.","Коли ж вони йшли сповістити учеників Його, ось Ісус зустрів їх і сказав: радуйтеся! Вони ж, приступивши, припали до ніг Його і вклонилися Йому.","Тоді говорить їм Ісус: не бійтеся; підіть сповістіть братів Моїх, щоб ішли до Галилеї, і там вони побачать Мене.","Коли ж вони йшли, то дехто зі сторожі, прийшовши до міста, сповістив первосвящеників про все, що сталося.","І вони, зібравшись із старійшинами, скликали раду, дали чимало грошей воїнам","і сказали: говоріть, що ученики Його, прийшовши вночі, украли Його, коли ми спали.","І якщо чутка про це дійде до правителя, ми переконаємо його і вас від неприємностей визволимо.","Вони, взявши гроші, зробили, як були навчені; і пронеслося слово це між юдеями, навіть до цього дня.","А одинадцять учеників пішли в Галилею, на гору, куди звелів їм Ісус.","І, побачивши Його, поклонилися Йому, а деякі засумнівались.","І, наблизившись, Ісус сказав їм: дана Мені всяка влада на небі і на землі.","Отже, йдіть, навчайте всі народи, хрестячи їх в ім’я Отця, і Сина, і Святого Духа,","навчаючи їх зберігати все, що Я заповів вам; і ось Я з вами по всі дні, до кінця віку. Амінь."],"x":{"1":"51.16.1|52.24.1|53.20.1","5":"51.16.6","6":"50.12.40|50.16.21|50.17.23","7":"50.26.32|51.14.28|53.21.1|54.1.3|54.10.41|63.15.5","9":"51.16.9|53.20.14","10":"53.20.17|75.2.11","18":"50.11.27|68.1.16|75.2.8|76.19.16|52.1.32|53.3.35|53.13.3|53.17.2|56.3.22|62.14.9|66.1.10|67.2.9"}}];
